  /** Required signature fields still unsigned on a report that is approved/closed. */
  private get pendingRequiredSignatures(): ReportSignatureField[] {
    const status = this.report()?.status;
    if (status !== 'APPROVED' && status !== 'CLOSED') return [];
    return (this.signatureStates()?.fields ?? []).filter(
      (f) => f.required && !f.signed,
    );
  }

  private get exportAction() {
    // Both entries always exist (the policy seeds them hidden + disabled), so pick the
    // one this role can actually see rather than the first that is defined.
    const actions = this.uiState?.actions;
    return actions?.['CUSTOMER_EXPORT']?.visible
      ? actions['CUSTOMER_EXPORT']
      : actions?.['ADMIN_EXPORT'];
  }

  /** Why Export is unavailable right now ('' = it is available). One source for every Export button. */
  public get exportBlockedReason(): string {
    const action = this.exportAction;
    if (action && !action.enabled && action.disabledReason) {
      return action.disabledReason;
    }
    if (!this.isOnline) return 'Export requires an internet connection.';
    const pending = this.pendingRequiredSignatures;
    if (pending.length > 0) {
      const who = pending
        .map(
          (f) =>
            `${f.label} (${f.signer === 'CUSTOMER' ? 'customer' : 'supervisor'})`,
        )
        .join(', ');
      return `Export is locked until the report is signed. Waiting for: ${who}.`;
    }
    return '';
  }

  public get exportAllowed(): boolean {
    return !!this.exportAction?.enabled && this.exportBlockedReason === '';
  }

  public isCustomer = computed(
    () => this.userRole().toUpperCase() === APP_ROLES.CUSTOMER,
  );
  /**
   * Milestone dates for the customer document identity band, derived from the
   * transition log (the report entity carries no created/received/approved
   * timestamps). `received` = first entry into RECEIVED; `completed` = the most
   * recent entry into APPROVED/CLOSED. Both null until the milestone is reached.
   */
  public customerKeyDates = computed<{
    received: string | null;
    completed: string | null;
  }>(() => {
    const logs = this.enrichedTransitionLogs(); // newest-first
    const received =
      [...logs].reverse().find((l) => l.toStatus === REPORT_STATUSES.RECEIVED)
        ?.timestamp ?? null;
    const completed =
      logs.find(
        (l) =>
          l.toStatus === REPORT_STATUSES.APPROVED ||
          l.toStatus === REPORT_STATUSES.CLOSED,
      )?.timestamp ?? null;
    return { received, completed };
  });
  /**
   * The customer's organisation name for the identity band. Reads the session
   * profile (`customer.name`, falling back to the tenant name) — the SAME source
   * the report list uses — rather than the ops `customerName` property, which is
   * resolved from the customers repo cache that never hydrates for a non-admin
   * (AdminCustomersService.canHydrate is ADMIN-only), so it would read 'N/A' here.
   * Customer surface only; the ops resolution of `customerName` is left untouched.
   */
  public customerDisplayName = computed<string>(() => {
    const p = this.session.profile();
    return p?.customer?.name || p?.tenant?.name || 'N/A';
  });

  // ---- Customer app frame (sidebar views + docked serial inspector) ----

  @ViewChild('cxaPane') cxaPaneRef?: ElementRef<HTMLElement>;

  /** The view the customer asked for (`?view=`); see `activeCustomerView` for what renders. */
  public customerView = signal<CustomerView>('overview');

  /**
   * Sidebar entries — a section appears only when it has something to show, from the
   * same signals that used to hide the document bands. Overview is always present.
   */
  public customerNav = computed<CustomerNavItem[]>(() => {
    const items: CustomerNavItem[] = [{ view: 'overview', label: 'Overview' }];
    if (this.hasSpecs()) items.push({ view: 'specs', label: 'Specifications' });
    if (this.statistics().length > 0) {
      items.push({ view: 'findings', label: 'Findings' });
    }
    const serialCount = this.filteredSerials().length;
    if (serialCount > 0) {
      items.push({
        view: 'serials',
        label: 'Serials',
        count: serialCount,
        unit: 'serial',
      });
    }
    const childCount = this.customerChildReports().length;
    if (childCount > 0) {
      items.push({
        view: 'children',
        label: 'Child reports',
        count: childCount,
        unit: 'report',
      });
    }
    const docCount = this.attachmentCount();
    if (docCount > 0) {
      items.push({
        view: 'documents',
        label: 'Documents',
        count: docCount,
        unit: 'file',
      });
    }
    if (this.enrichedTransitionLogs().length > 0) {
      items.push({ view: 'history', label: 'History' });
    }
    return items;
  });

  /**
   * What actually renders: the requested view while it has content, else Overview.
   * Sections measured after first render (specs, documents) fall back briefly and then
   * resolve to the requested view once their content is known — the request is kept.
   */
  public activeCustomerView = computed<CustomerView>(() => {
    const wanted = this.customerView();
    return this.customerNav().some((i) => i.view === wanted)
      ? wanted
      : 'overview';
  });

  public activeCustomerNavItem = computed<CustomerNavItem>(
    () =>
      this.customerNav().find((i) => i.view === this.activeCustomerView()) ?? {
        view: 'overview',
        label: 'Overview',
      },
  );

  /** Below 1024px the sidebar is a horizontal segmented bar: keep the active segment visible. */
  private readonly keepActiveSegmentInView = effect(() => {
    this.activeCustomerView();
    setTimeout(() => {
      const item = document.querySelector<HTMLElement>(
        '.cxa-nav-item.is-active',
      );
      const bar = item?.closest<HTMLElement>('.cxa-sidebar');
      if (!item || !bar || bar.scrollWidth <= bar.clientWidth) return;
      bar.scrollTo({
        left: item.offsetLeft - (bar.clientWidth - item.offsetWidth) / 2,
        behavior: 'smooth',
      });
    });
  });

  public setCustomerView(view: CustomerView): void {
    if (view === this.activeCustomerView()) return;
    // The inspector belongs to one list (report serials or a child's) — never carry it over.
    this.closeInspectionForm();
    this.customerView.set(view);
    this.selectedChildId.set(null);
    this.selectedFindingId.set(null);
    this.cxaPaneRef?.nativeElement.scrollTo({ top: 0 });
    this.syncCustomerQuery();
  }

  private syncCustomerQuery(): void {
    const view = this.customerView();
    void this.router.navigate([], {
      relativeTo: this.route,
      queryParams: {
        view: view === 'overview' ? null : view,
        child: view === 'children' ? this.selectedChildId() : null,
        finding: view === 'findings' ? this.selectedFindingId() : null,
      },
      queryParamsHandling: 'merge',
      replaceUrl: true,
    });
  }

  /** Child report picked from the list (`?child=`); ignored when there is only one. */
  public selectedChildId = signal<string | null>(null);

  /** The child shown in detail: the only one, or the one picked from the list. */
  public activeChild = computed<LocalChildReport | null>(() => {
    const children = this.customerChildReports();
    if (children.length === 1) return children[0] ?? null;
    const id = this.selectedChildId();
    return children.find((c) => c.id === id) ?? null;
  });

  /** The active child's serials, in the shape the shared customer table and inspector read. */
  public activeChildSerials = computed<LocalSerialNumber[]>(() => {
    const child = this.activeChild();
    if (!child) return [];
    return [...child.serialNumbers]
      .sort((a, b) =>
        a.serial.localeCompare(b.serial, undefined, {
          numeric: true,
          sensitivity: 'base',
        }),
      )
      .map(
        (s) =>
          ({
            id: s.id,
            inspectionReportId: child.inspectionReportId,
            value: s.serial,
            version: 0,
            inspectionJson: s.inspectionData,
            approvalStatus: s.approvalStatus,
          }) as LocalSerialNumber,
      );
  });

  // ---- Findings (master-detail: statistic list → its serials) ----

  /** Statistic picked in the Findings list (`?finding=`); defaults to the first one. */
  public selectedFindingId = signal<string | null>(null);

  public activeFinding = computed<ReportStatistic | null>(() => {
    const stats = this.statistics();
    const id = this.selectedFindingId();
    return stats.find((s) => s.id === id) ?? stats[0] ?? null;
  });

  /** The report serials a statistic links to, in the table's (natural-sorted) order. */
  public findingSerials = computed<LocalSerialNumber[]>(() => {
    const finding = this.activeFinding();
    if (!finding) return [];
    const wanted = new Set(finding.serials);
    return this.filteredSerials().filter((sn) => wanted.has(sn.value));
  });

  /** Share of the report's serials a statistic links to (0–1). */
  public findingCoverage(stat: ReportStatistic): number {
    const total = this.serials().length;
    return total > 0 ? Math.min(1, stat.serials.length / total) : 0;
  }

  public selectFinding(id: string): void {
    if (id === this.activeFinding()?.id) return;
    this.closeInspectionForm();
    this.selectedFindingId.set(id);
    this.syncCustomerQuery();
  }

  // ---- History (plain event log; timing analytics are admin-only, see features/metrics) ----

  public readonly historyEventLabel = eventLabel;

  public openChild(id: string): void {
    this.closeInspectionForm();
    this.selectedChildId.set(id);
    this.cxaPaneRef?.nativeElement.scrollTo({ top: 0 });
    this.syncCustomerQuery();
  }

  public closeChild(): void {
    this.closeInspectionForm();
    this.selectedChildId.set(null);
    this.syncCustomerQuery();
  }

  /** Step to the previous/next visible sidebar view (`←` / `→`). */
  public stepCustomerView(delta: number): void {
    const nav = this.customerNav();
    const index = nav.findIndex((i) => i.view === this.activeCustomerView());
    const next = nav[index + delta];
    if (next) this.setCustomerView(next.view);
  }

  /** Docked inspector width (px) — resizable, remembered per browser. */
  public inspectorWidth = signal<number>(this.readInspectorWidth());
  private resizePointerId: number | null = null;

  private readInspectorWidth(): number {
    try {
      const stored = Number(localStorage.getItem(INSPECTOR_WIDTH_KEY));
      if (Number.isFinite(stored) && stored >= INSPECTOR_MIN_WIDTH)
        return stored;
    } catch {
      /* storage unavailable — default width */
    }
    return INSPECTOR_DEFAULT_WIDTH;
  }

  private setInspectorWidth(px: number): void {
    const max = Math.max(INSPECTOR_MIN_WIDTH, window.innerWidth * 0.5);
    this.inspectorWidth.set(
      Math.round(Math.min(max, Math.max(INSPECTOR_MIN_WIDTH, px))),
    );
  }

  private persistInspectorWidth(): void {
    try {
      localStorage.setItem(INSPECTOR_WIDTH_KEY, String(this.inspectorWidth()));
    } catch {
      /* storage unavailable — the width just won't persist */
    }
  }

  public startInspectorResize(event: PointerEvent): void {
    const handle = event.currentTarget as HTMLElement;
    handle.setPointerCapture(event.pointerId);
    this.resizePointerId = event.pointerId;
    event.preventDefault();
  }

  public onInspectorResize(event: PointerEvent): void {
    if (this.resizePointerId !== event.pointerId) return;
    const inspector = (event.currentTarget as HTMLElement).parentElement;
    if (!inspector) return;
    this.setInspectorWidth(
      inspector.getBoundingClientRect().right - event.clientX,
    );
  }

  public endInspectorResize(event: PointerEvent): void {
    if (this.resizePointerId !== event.pointerId) return;
    this.resizePointerId = null;
    this.persistInspectorWidth();
  }

  /** Keyboard resize on the focused handle: ←/→ widen/narrow by 24px. */
  public nudgeInspector(event: KeyboardEvent): void {
    if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return;
    event.preventDefault();
    event.stopPropagation();
    this.setInspectorWidth(
      this.inspectorWidth() + (event.key === 'ArrowLeft' ? 24 : -24),
    );
    this.persistInspectorWidth();
  }

  /** Esc closes the statistic serials modal wherever focus is. */
  @HostListener('document:keydown.escape')
  public onEscapeStatisticModal(): void {
    if (this.activeStatistic()) this.closeStatisticModal();
  }

  /** App-style shortcuts for the customer frame. Ignored while typing or under a modal. */
  @HostListener('document:keydown', ['$event'])
  public onCustomerShortcut(event: KeyboardEvent): void {
    if (!this.isCustomer() || event.defaultPrevented || this.activeStatistic())
      return;
    const target = event.target;
    if (
      target instanceof Element &&
      target.closest(
        'input, textarea, select, [contenteditable="true"], [role="dialog"]',
      )
    ) {
      return;
    }
    if (event.ctrlKey || event.metaKey || event.altKey) return;

    if (event.key === 'Escape' && this.inspectingSn()) {
      event.preventDefault();
      this.closeInspectionForm();
    } else if (
      (event.key === 'ArrowDown' || event.key === 'j') &&
      this.inspectingSn()
    ) {
      event.preventDefault();
      this.goToNextSn();
    } else if (
      (event.key === 'ArrowUp' || event.key === 'k') &&
      this.inspectingSn()
    ) {
      event.preventDefault();
      this.goToPrevSn();
    } else if (event.key === 'ArrowRight') {
      event.preventDefault();
      this.stepCustomerView(1);
    } else if (event.key === 'ArrowLeft') {
      event.preventDefault();
      this.stepCustomerView(-1);
    }
  }

  /** The list prev/next walks: customers step through the rows they see. */
  private navSerials(): LocalSerialNumber[] {
    if (!this.isCustomer()) return this.serials();
    switch (this.activeCustomerView()) {
      case 'children':
        return this.activeChildSerials();
      case 'findings':
        return this.findingSerials();
      default:
        return this.filteredSerials();
    }
  }
  /**
   * Badge severity for the report status shown in the customer identity band —
   * a settled/approved report reads success, a held one warning, one under
   * review info, everything mid-flight neutral. Presentational only.
   */
  public reportStatusSeverity = computed<BadgeSeverity>(() => {
    switch (this.report()?.status) {
      case REPORT_STATUSES.APPROVED:
      case REPORT_STATUSES.CLOSED:
        return 'success';
      case REPORT_STATUSES.ON_HOLD:
        return 'warning';
      case REPORT_STATUSES.PENDING_APPROVAL:
        return 'info';
      default:
        return 'neutral';
    }
  });
  public isReceiver = computed(
    () => this.userRole().toUpperCase() === APP_ROLES.RECEIVER,
  );
  public isSupervisor = computed(
    () => this.userRole().toUpperCase() === APP_ROLES.SUPERVISOR,
  );
  public canAccessBatchApprovals = computed(() => {
    const role = this.userRole().toUpperCase();
    return (
      role === APP_ROLES.INSPECTOR ||
      role === APP_ROLES.SUPERVISOR ||
      role === APP_ROLES.ADMIN
    );
  });
  /** SUPERVISOR has the same powers as ADMIN on a report, so both count here. */
  public isAdmin = computed(() => {
    const role = this.userRole().toUpperCase();
    return role === APP_ROLES.ADMIN || role === APP_ROLES.SUPERVISOR;
  });
  public isLocked = computed(() => {
    const report = this.report();
    if (!report) return false;
    return (
      report.status === REPORT_STATUSES.APPROVED ||
      report.status === REPORT_STATUSES.CLOSED
    );
  });

  public isTransitionExpanded = true;

  public canPublishReport = computed(() => {
    const role = this.userRole().toUpperCase();
    const isSuperOrAdmin =
      role === APP_ROLES.SUPERVISOR || role === APP_ROLES.ADMIN;
    const currentStatus = this.report()?.status;
    const serials = this.serials();

    const hasSerials = serials && serials.length > 0;
    const allSerialsApproved =
      hasSerials &&
      serials.every((sn) => sn.approvalStatus === SERIAL_STATUSES.APPROVED);

    return (
      isSuperOrAdmin &&
      allSerialsApproved &&
      currentStatus !== REPORT_STATUSES.APPROVED &&
      currentStatus !== REPORT_STATUSES.CLOSED
    );
  });

  public historyNotes = computed(() => {
    const sn = this.activeHistorySn();
    if (!sn) return [];

    return this.approvalBatches()
      .filter((b) => b.batch.notes && b.serials.some((s) => s.id === sn.id))
      .map((b) => ({
        notes: b.batch.notes,
        date: b.batch.submittedAt,
        user: b.submittedByName,
      }))
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  });

  public historySerialIds = computed(() => {
    const ids = new Set<string>();

    for (const batch of this.approvalBatches()) {
      if (
        batch.batch.status !== BATCH_STATUSES.RETURNED ||
        !batch.batch.notes
      ) {
        continue;
      }

      for (const serial of batch.serials) {
        ids.add(serial.id);
      }
    }

    return ids;
  });

  public get isOnline(): boolean {
    return this.connectivity.isOnline();
  }

  public getDisposition(sn: LocalSerialNumber): string | null {
    if (!sn.inspectionJson) return null;
    // Resolve through the shared definition-driven resolver so the detail KPIs/Findings
    // read disposition from wherever THIS template declares (disposition.source) —
    // identical to the server gate and every other client surface. No hardcoded field.
    return resolveDisposition(sn.inspectionJson, this.reportDefinition);
  }

  async ngOnInit() {
    this.reportId = this.route.snapshot.paramMap.get('id') || '';
    const requestedView = this.route.snapshot.queryParamMap.get('view');
    if (CUSTOMER_VIEWS.includes(requestedView as CustomerView)) {
      this.customerView.set(requestedView as CustomerView);
    }
    this.selectedChildId.set(this.route.snapshot.queryParamMap.get('child'));
    this.selectedFindingId.set(
      this.route.snapshot.queryParamMap.get('finding'),
    );
    if (this.reportId && this.reportId !== 'reports') {
      this.refreshData();

      toObservable(this.irService.reports, {
        injector: this.injector,
      }).subscribe(() => {
        this.refreshData();
      });

      this.crService.changes$.subscribe(() => {
        this.refreshData();
      });

      if (
        !this.reportId.startsWith('local-ir-') &&
        this.reportId !== 'create'
      ) {
        await this.irService.refreshAvailableTransitions(this.reportId);
        await this.irService.refreshTransitionLogs(this.reportId);
        if (this.canAccessBatchApprovals()) {
          await this.irService.pullBatchesForReport(this.reportId);
        }
        await this.crService.pullForInspectionFromServer(this.reportId);
      }
    }
  }

  private async refreshData() {
    // 1. Fetch all data asynchronously without mutating component state yet
    const list = await this.irService.irRepo.list();
    const r =
      list.find((x: LocalInspectionReport) => x.id === this.reportId) || null;

    const snList = await this.irService.getSnForReport(this.reportId);
    const logs = await this.irService.getTransitionLogsLocally(this.reportId);

    // Enrich logs with user names
    const enrichedLogs = [];
    for (const log of logs) {
      let userName = 'Unknown';
      if (log.userId) {
        const u = await this.userRepo.getById(log.userId);
        if (u) userName = u.name || u.email;
      }
      enrichedLogs.push({ ...log, userName });
    }
    // Sort by timestamp desc for timeline feel (newest first)
    enrichedLogs.sort(
      (a, b) =>
        new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime(),
    );

    const childReports = await this.crService.getChildReportsForInspection(
      this.reportId,
    );

    // Load batches
    const batches = await this.approvalBatchRepo.listByReportId(this.reportId);
    const enrichedBatches = [];
    for (const batch of batches) {
      const bsnList = await this.batchSnRepo.listByBatchId(batch.id);
      const snMap = new Map(
        bsnList.map((b) => [b.serialNumberId, b.status || 'PENDING']),
      );
      const batchSerials = snList
        .filter((sn) => snMap.has(sn.id))
        .map((sn) => ({
          ...sn,
          batchStatus: snMap.get(sn.id),
        }));

      let submittedByName = 'Unknown';
      if (batch.submittedByUserId) {
        const u = await this.userRepo.getById(batch.submittedByUserId);
        if (u) submittedByName = u.name || u.email;
      }

      let reviewedByName = 'Unknown';
      if (batch.reviewedByUserId) {
        const reviewer = await this.userRepo.getById(batch.reviewedByUserId);
        if (reviewer) {
          reviewedByName = reviewer.name || reviewer.email;
        }
      }

      enrichedBatches.push({
        batch,
        serials: batchSerials,
        submittedByName,
        reviewedByName,
      });
    }
    // Sort batches by submittedAt desc
    enrichedBatches.sort(
      (a, b) =>
        new Date(b.batch.submittedAt).getTime() -
        new Date(a.batch.submittedAt).getTime(),
    );

    let vResult = null;
    let previousStatus: string | null = null;
    let onHoldReason: string | null = null;
    let newUiState = null;
    let newCustomerAddress = 'N/A';
    let newCustomerName = 'N/A';
    let newInspectedByName = 'N/A';
    let newApprovedByName = 'N/A';

    if (r) {
      vResult = this.validationService.validate(r, snList);
      if (this.isReceiver()) {
        vResult = this.validationService.scopeToReceiver(vResult);
      }

      const pending = await this.outboxRepo.getPendingItems();
      const conflicts = await this.outboxRepo.getConflictItems();
      const transitionOutbox = [...pending, ...conflicts].filter(
        (i) =>
          i.entityType === ENTITY_TYPES.INSPECTION_REPORT &&
          i.entityId === this.reportId &&
          i.operation === 'TRANSITION' &&
          i.lastError,
      );

      for (const t of transitionOutbox) {
        vResult.issues.push({
          code: 'BACKEND_REJECTION',
          level: 'BLOCKER',
          message: `Server Rejected Transition: ${t.lastError}`,
          scope: 'REPORT',
        });
        vResult.isReady = false;
      }

      if (r.status === REPORT_STATUSES.ON_HOLD && logs.length > 0) {
        const sortedLogs = [...logs].sort(
          (a, b) =>
            new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime(),
        );
        const toHold = sortedLogs.find(
          (l) => l.toStatus === REPORT_STATUSES.ON_HOLD,
        );
        if (toHold) {
          previousStatus = toHold.fromStatus;
          onHoldReason = toHold.reason || null;
        }
      }

      newUiState = getInspectionReportUiState({
        role: this.userRole() as AppRole,
        reportStatus: r.status as ReportStatus,
        isOffline: !this.isOnline,
        hasValidationIssues: !vResult.isReady,
        syncState: r.syncState as SyncState,
        previousStatus: previousStatus,
        onHoldReason: onHoldReason,
        version: r.version,
      });

      // Meta Card Calcs
      if (r.customerId) {
        const cust = await this.customerRepo.getById(r.customerId);
        if (cust) {
          newCustomerName = cust.name?.trim() || 'N/A';
          const parts = [
            cust.addressLine1,
            cust.addressLine2,
            cust.city,
            cust.country,
          ].filter((x) => x && x.trim().length > 0);
          newCustomerAddress = parts.length > 0 ? parts.join(', ') : 'N/A';
        }
      }

      if (logs.length > 0) {
        const sortedAsc = [...logs].sort(
          (a, b) =>
            new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime(),
        );
        // Inspected By: whoever last acted on the inspection (server-derived and
        // name-resolved, so a reopen with nothing new done keeps the earlier inspector
        // and every role sees it). Reports not yet pulled with detail fall back to who
        // first started the inspection, via the local user cache.
        if (r.inspectorName) {
          newInspectedByName = r.inspectorName;
        } else {
          const starter = sortedAsc.find(
            (l) => l.toStatus === REPORT_STATUSES.IN_INSPECTION,
          )?.userId;
          if (starter) {
            const u = await this.userRepo.getById(starter);
            newInspectedByName = u?.name || u?.email || 'N/A';
          }
        }

        // Approved By: Last user who transitioned to APPROVED
        const approveLog = [...sortedAsc]
          .reverse()
          .find(
            (l) =>
              l.toStatus === REPORT_STATUSES.APPROVED ||
              l.toStatus === REPORT_STATUSES.CLOSED,
          );
        if (approveLog && approveLog.userId) {
          const u = await this.userRepo.getById(approveLog.userId);
          newApprovedByName = u?.name || u?.email || 'N/A';
        } else {
          const latestApprovedBatch = enrichedBatches
            .filter((b) => b.batch.status === BATCH_STATUSES.APPROVED)
            .sort(
              (a, b) =>
                new Date(b.batch.reviewedAt || b.batch.submittedAt).getTime() -
                new Date(a.batch.reviewedAt || a.batch.submittedAt).getTime(),
            )[0];

          if (latestApprovedBatch?.reviewedByName) {
            newApprovedByName = latestApprovedBatch.reviewedByName;
          }
        }
      }
    }

    // System-owned (roled) header values — assembled from the SAME derivation just
    // computed (inspector/approver names) plus the report's updatedAt for the date. No
    // second derivation: a roled field's row reads straight from this map. 'N/A' (the
    // no-actor sentinel above) → a neutral pending state naming what it waits on.
    const dateValue = r?.updatedAt
      ? formatDate(r.updatedAt, 'mediumDate', 'en-US')
      : '';
    const reportNumberValue = r?.reportNumber?.trim() || '';
    const poNumberValue = r?.poNumber?.trim() || '';
    const newSystemRoleValues: SystemRoleValues = {
      // Set-at-creation roles: the report already carries these once it exists, so they are
      // never pending in practice — but keep the neutral pending fallback for a not-yet-
      // assigned value rather than showing a blank cell.
      customer: {
        value: newCustomerName,
        pending: newCustomerName === 'N/A',
        pendingLabel: 'Awaiting customer',
        source: 'Set at creation',
      },
      reportNumber: {
        value: reportNumberValue,
        pending: !reportNumberValue,
        pendingLabel: 'Assigned on first sync',
        source: 'Set at creation',
      },
      poNumber: {
        value: poNumberValue,
        pending: !poNumberValue,
        pendingLabel: 'Awaiting PO number',
        source: 'Set at creation',
      },
      inspector: {
        value: newInspectedByName,
        pending: newInspectedByName === 'N/A',
        pendingLabel: 'Awaiting inspection',
        source: 'Set at inspection',
      },
      supervisor: {
        value: newApprovedByName,
        pending: newApprovedByName === 'N/A',
        pendingLabel: 'Awaiting approval',
        source: 'Set at approval',
      },
      inspectionDate: {
        value: dateValue,
        pending: !dateValue,
        pendingLabel: 'Set on first save',
        source: 'Set automatically',
      },
      // Not entered anywhere: the inspector's account signature is frozen at submission
      // and placed on the exported workbook. Always shown as a neutral pending state.
      inspectorSignature: {
        value: '',
        pending: true,
        pendingLabel: 'Applied at export',
        source: "From the inspector's account signature",
      },
    };

    // --- APPLY ALL STATE SYNCHRONOUSLY AT THE END ---
    this.report.set(r);
    this.serials.set(snList);
    this.transitionLogs.set(logs);
    this.enrichedTransitionLogs.set(enrichedLogs);
    this.childReports.set(childReports);
    this.approvalBatches.set(enrichedBatches);

    if (r) {
      this.validationResult = vResult;
      this.uiState = newUiState;
      this.allowedTransitions = newUiState ? newUiState.transitionChoices : [];
      this.customerAddress = newCustomerAddress;
      this.customerName = newCustomerName;
      this.inspectedByName = newInspectedByName;
      this.approvedByName = newApprovedByName;
      this.systemRoleValues = newSystemRoleValues;

      // Set default tab if not set
      if (this.activeTab() === 'summary') {
        const hasRedirectedTab = sessionStorage.getItem('hasRedirectedTab');

        if (!hasRedirectedTab) {
          const role = this.userRole().toUpperCase();
          if (role === APP_ROLES.INSPECTOR) {
            this.activeTab.set('serials');
            sessionStorage.setItem('hasRedirectedTab', 'true');
          } else if (role === APP_ROLES.SUPERVISOR) {
            this.activeTab.set(
              this.hasPendingApprovals() ? 'approvals' : 'serials',
            );
            sessionStorage.setItem('hasRedirectedTab', 'true');
          }
        }
      }

      // Header-scope fields are no longer hydrated into a `form*` scaffold — the
      // generic header-edit component seeds itself from `[data]` (the header view).
      // Only the standalone global-comment editor keeps a model here, read from the
      // generic `headerData` store (the sole header source after step 3) so a Specs
      // edit of the comment shows through.
      if (!this.isEditingGlobalComment()) {
        const generic =
          r.headerData && typeof r.headerData === 'object'
            ? (r.headerData as Record<string, unknown>)
            : {};
        this.formGlobalComment =
          typeof generic['inspectorComment'] === 'string'
            ? (generic['inspectorComment'] as string)
            : '';
      }
    } else {
      this.validationResult = null;
      this.uiState = null;
      this.allowedTransitions = [];
    }

    setTimeout(() => this.setupShellScrollTracking(), 0);
  }

  public async onAddSerials() {
    this.formError = '';
    const rawLines = this.formBulkSerials
      .split('\n')
      .filter((l) => l.trim().length > 0);
    if (rawLines.length === 0) return;

    const lines = rawLines.map((l) => l.trim());
    const uniqueLines = [...new Set(lines)];
    if (uniqueLines.length !== lines.length) {
      this.formError = 'Duplicate serial numbers found in the input list.';
      return;
    }

    const existingSns = this.serials();
    const existingVals = new Set(existingSns.map((s) => s.value.toLowerCase()));
    const duplicates = uniqueLines.filter((l) =>
      existingVals.has(l.toLowerCase()),
    );

    if (duplicates.length > 0) {
      this.formError = `These serial numbers already exist in this report: ${duplicates.join(', ')}`;
      return;
    }

    try {
      await this.irService.addSerialNumbers(this.reportId, uniqueLines);
      this.formBulkSerials = '';
      this.refreshData();
    } catch (error) {
      const e = error as Error;
      this.formError = e.message || 'Failed to add serials.';
    }
  }

