  public editMetadataFromSummary(): void {
    this.isEditingMeta.set(true);
    this.onTabClick('specs');
  }

  /**
   * Whether a tab should surface a static attention badge. Same role/status/data
   * conditions the old pulse used, minus the persisted per-tab dismissal — the
   * localStorage pulse preferences are intentionally no longer read.
   */
  public tabNeedsAttention(tab: string): boolean {
    const report = this.report();
    if (!report || this.isCustomer()) {
      return false;
    }

    const status = report.status as string;
    const sns = this.serials();
    const hasUninspected =
      sns.length === 0 ||
      sns.some((sn) => sn.approvalStatus === SERIAL_STATUSES.NOT_INSPECTED);

    if (tab === 'approvals') {
      return this.canAccessBatchApprovals() && this.hasPendingApprovals();
    }

    if (tab === 'serials') {
      if (
        (this.isReceiver() || this.isAdmin()) &&
        ['DRAFT', 'RECEIVED', 'READY_FOR_CLEANING'].includes(status)
      ) {
        return true;
      }

      if (
        (this.userRole() === APP_ROLES.INSPECTOR || this.isAdmin()) &&
        (status === REPORT_STATUSES.READY_FOR_INSPECTION ||
          status === REPORT_STATUSES.IN_INSPECTION)
      ) {
        if (hasUninspected) return true;
      }

      if (
        (this.isSupervisor() || this.isAdmin()) &&
        (status === REPORT_STATUSES.IN_INSPECTION ||
          status === REPORT_STATUSES.PENDING_APPROVAL)
      ) {
        if (!this.hasPendingApprovals()) return true;
      }
      return false;
    }

    if (tab === 'summary' || tab === 'specs') {
      if (
        (this.userRole() === APP_ROLES.INSPECTOR || this.isAdmin()) &&
        (status === REPORT_STATUSES.READY_FOR_INSPECTION ||
          status === REPORT_STATUSES.IN_INSPECTION)
      ) {
        if (!hasUninspected && sns.length > 0) {
          return true;
        }
      }
      return false;
    }

    return false;
  }

  public tabTooltip(tab: 'serials' | 'approvals'): string {
    if (tab === 'approvals' && this.tabNeedsAttention('approvals')) {
      return 'Pending approvals require review';
    }

    if (tab === 'serials' && this.tabNeedsAttention('serials')) {
      return 'Inspect pipes and set dispositions';
    }

    return '';
  }

  public openHistory(sn: LocalSerialNumber): void {
    this.activeHistorySn.set(sn);
  }

  public closeHistory(): void {
    this.activeHistorySn.set(null);
  }
}

import {
  Component,
  EventEmitter,
  Input,
  Output,
  computed,
  effect,
  inject,
  signal,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { sameContent } from '@portal/shared/utils/same-content';
import {
  AbstractControl,
  FormBuilder,
  FormGroup,
  ReactiveFormsModule,
  Validators,
} from '@angular/forms';
import {
  FieldSchema,
  FormSchema,
} from '@portal/features/templates/schemas/drill-pipe-v1.schema';
import {
  TemplateFormDefinition,
  definitionToFormSchema,
  SystemRoleValues,
} from '@portal/features/templates/schemas/definition-to-form-schema';
import {
  isObjectListRowEmpty,
  toObjectListRow,
} from '@portal/features/templates/schemas/object-list-field';
import { DefinitionFieldInputComponent } from '@portal/features/inspections/components/definition-field-input/definition-field-input.component';
import { SystemFieldRowComponent } from './system-field-row.component';

/**
 * Editable counterpart to `InspectionReportHeaderFieldsComponent` — the generic,
 * definition-driven header edit form (the Specs tab). It renders EVERY header-scope
 * field from the definition through the shared `DefinitionFieldInputComponent`
 * primitive, which dispatches purely on the declared field TYPE — no field-name
 * awareness, no hardcoded drill-pipe markup (scalars → a single control, `object-list`
 * → the generic `{ name, number }` array editor that ANY array field uses).
 *
 * On save it emits ONE definition-keyed header map (fieldKey → value); the parent
 * persists it to the report's generic `headerData` store (never per-named-column).
 * Fallback discipline mirrors the read-only view and the item form EXACTLY: a
 * null/undefined/malformed definition, or one with no header fields, drives the
 * explicit empty-state — NEVER a drill-pipe fallback.
 */
@Component({
  selector: 'app-inspection-report-header-edit',
  standalone: true,
  imports: [
    CommonModule,
    ReactiveFormsModule,
    DefinitionFieldInputComponent,
    SystemFieldRowComponent,
  ],
  templateUrl: './inspection-report-header-edit.component.html',
})
export class InspectionReportHeaderEditComponent {
  /** The report's template definition (report.definitionJson), or null pre-cutover. */
  @Input() set definition(value: TemplateFormDefinition | null) {
    this._definition.set(value ?? null);
  }
  /** The report row — header field VALUES seed the form by field key. */
  @Input() set data(value: Record<string, unknown> | null) {
    this._data.set(value ?? {});
  }
  /**
   * Derived values for roled (system-owned) fields. A roled field builds NO control and
   * emits nothing on save — it renders the read-only System row from these values instead.
   */
  @Input() systemValues: SystemRoleValues = {};

  /** Emits the definition-keyed header map (fieldKey → value) on save. */
  @Output() save = new EventEmitter<Record<string, unknown>>();
  /** Emits when the user cancels the edit. */
  @Output() cancelEdit = new EventEmitter<void>();

  // Content-equality, not reference-equality: window-focus hydration hands the parent a
  // fresh-but-identical report object, which would otherwise rebuild the form and wipe
  // whatever the user has typed.
  private _definition = signal<TemplateFormDefinition | null>(null, {
    equal: sameContent,
  });
  private _data = signal<Record<string, unknown>>({}, { equal: sameContent });
  private fb = inject(FormBuilder);

  /** The header schema, or null when there is no usable definition. Soft-null. */
  public schema = computed<FormSchema | null>(() => {
    const def = this._definition();
    if (!def) return null;
    try {
      return definitionToFormSchema(def, { scope: 'header' });
    } catch {
      return null;
    }
  });

  /** True → render the explicit empty-state (no usable definition, or zero fields). */
  public schemaUnavailable = computed(() => {
    const s = this.schema();
    if (!s) return true;
    return s.sections.every((sec) => sec.fields.length === 0);
  });

  /** The reactive form, rebuilt whenever the schema or seed data changes. */
  public form = signal<FormGroup>(this.fb.group({}));

  constructor() {
    // Rebuild the form when the definition (→ schema) or the seed data changes.
    // Scheduler-driven; a re-point of either input reactively re-renders the form.
    effect(() => {
      const schema = this.schema();
      const data = this._data();
      this.form.set(this.buildForm(schema, data));
    });
  }

  private buildForm(
    schema: FormSchema | null,
    data: Record<string, unknown>,
  ): FormGroup {
    const group: Record<string, unknown> = {};
    if (!schema) return this.fb.group(group);
    for (const section of schema.sections) {
      for (const field of section.fields) {
        // Roled (system-owned) fields are not user-writable: build NO control, add NO
        // required validator. They render as read-only System rows in the template.
        if (field.role) continue;
        const raw = data[field.key];
        if (field.inputType === 'object-list') {
          const rows = Array.isArray(raw) ? raw : [];
          group[field.key] = this.fb.array(
            rows.map((row) => this.fb.group(toObjectListRow(row))),
          );
        } else {
          // Scalars (incl. boolean, now a tri-state select) — seed the raw value or ''.
          const validators = field.required ? [Validators.required] : [];
          group[field.key] = this.fb.control(raw ?? '', validators);
        }
      }
    }
    return this.fb.group(group);
  }

  /** The control backing a field, handed to the shared input primitive. */
  public controlFor(key: string): AbstractControl {
    return this.form().get(key)!;
  }

  public getFieldOptions(field: FieldSchema): string[] {
    return field.options ?? [];
  }

  public onSave(): void {
    const form = this.form();
    if (form.invalid) {
      form.markAllAsTouched();
      return;
    }
    const schema = this.schema();
    const raw = form.getRawValue() as Record<string, unknown>;
    const out: Record<string, unknown> = {};
    for (const section of schema?.sections ?? []) {
      for (const field of section.fields) {
        // Roled fields have no control and are never emitted — their value is derived.
        if (field.role) continue;
        const value = raw[field.key];
        if (field.inputType === 'object-list') {
          // Normalize to the shared `{ name, number }` row shape and drop empty rows —
          // the shape the export transforms consume. No field-name coupling.
          const rows = (Array.isArray(value) ? value : []).map(toObjectListRow);
          out[field.key] = rows.filter((r) => !isObjectListRowEmpty(r));
        } else {
          out[field.key] = value;
        }
      }
    }
    this.save.emit(out);
  }

  public onCancel(): void {
    this.cancelEdit.emit();
  }
}

import { RevealDirective } from '@portal/shared/directives/reveal.directive';
import { ReportLifecycleRailComponent } from '@portal/shared/components/report-lifecycle-rail/report-lifecycle-rail.component';
import {
  Component,
  inject,
  OnInit,
  Input,
  OnDestroy,
  ChangeDetectorRef,
  Injector,
  signal,
  computed,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { Subscription, combineLatest, startWith } from 'rxjs';
import { toObservable } from '@angular/core/rxjs-interop';
import { InspectionReportsService } from '@portal/features/inspections/services/inspection-reports.service';
import { ReportDeleteFlowService } from '@portal/features/inspections/services/report-delete-flow.service';
import { ToastService } from '@portal/shared/toast/toast.service';
import { CustomerLocalRepo } from '@portal/core/offline/repos/customer-local.repo';
import { SyncOrchestratorService } from '@portal/core/offline/services/sync-orchestrator.service';
import { FormsModule } from '@angular/forms';
import {
  LocalChildReport,
  LocalCustomer,
  LocalInspectionReport,
  LocalSerialNumber,
} from '@portal/core/offline/models/types';
import {
  ReportValidationService,
  ValidationResult,
} from '@portal/core/validation/services/report-validation.service';
import { SerialNumberLocalRepo } from '@portal/core/offline/repos/serial-number-local.repo';
import { ChildReportLocalRepo } from '@portal/core/offline/repos/child-report-local.repo';
import { SessionService } from '@portal/core/auth/services/session.service';
import { UserPreferencesService } from '@portal/core/services/user-preferences.service';
import {
  APP_ROLES,
  REPORT_STATUSES,
} from '@portal/core/constants/app.constants';
import { BadgeSeverity } from '@portal/shared/components/status-badge/status-badge.component';

@Component({
  selector: 'app-inspection-report-list',
  standalone: true,
  imports: [
    ReportLifecycleRailComponent,
    RevealDirective,
    CommonModule,
    RouterModule,
    FormsModule,
  ],
  templateUrl: './inspection-report-list.component.html',
})
export class InspectionReportListComponent implements OnInit, OnDestroy {
  private irService = inject(InspectionReportsService);
  private customerRepo = inject(CustomerLocalRepo);
  public syncOrchestrator = inject(SyncOrchestratorService);
  private validationService = inject(ReportValidationService);
  private snRepo = inject(SerialNumberLocalRepo);
  private childReportRepo = inject(ChildReportLocalRepo);
  private sessionService = inject(SessionService);
  public prefs = inject(UserPreferencesService);
  private cdr = inject(ChangeDetectorRef);
  private injector = inject(Injector);
  private deleteFlow = inject(ReportDeleteFlowService);
  private toast = inject(ToastService);

  public reports = this.irService.reports;
  public customers = signal<LocalCustomer[]>([]);

  public statusFilter = '';
  public customerFilter = '';
  public qFilter = '';
  public snFilter = '';
  public sortBy: 'updatedAt' | 'poNumber' | 'status' = 'updatedAt';

  public isCustomer = false;
  public isReceiver = false;
  public isAdmin = false;
  public isSupervisor = false;
  private customerScopeId: string | null = null;

  public kpiTotalReports = 0;
  public kpiOpenReports = 0;
  public kpiClosedReports = 0;

  public reportStatsCache: Record<
    string,
    { serialCount: number; serialValues: string[] }
  > = {};
  public validationCache: Record<string, ValidationResult> = {};
  /** Child reports (rework / scrap / hold) per parent report id — customer list only. */
  public childReportsByReport = signal<Record<string, LocalChildReport[]>>({});
  public isCompactMode = computed(() => this.prefs.preferences().compactMode);
  private subs = new Subscription();

  /**
   * Fade-before-reflow phase for the customer document list. A discrete status
   * or sort change fades the list body OUT (accelerate), swaps the data while
   * it's invisible so the height reflow isn't seen, then settles it back IN
   * (decelerate) — the marketing site's signature rule, at app scale. Idle when
   * nothing is transitioning. Search-as-you-type is deliberately excluded so
   * typing feedback stays instant.
   */
  public listPhase = signal<'idle' | 'out' | 'in'>('idle');
  private reflowTimers: ReturnType<typeof setTimeout>[] = [];

  @Input() initialStatusFilter?: string;

  ngOnInit() {
    if (this.initialStatusFilter) {
      this.statusFilter = this.initialStatusFilter;
    }
    this.irService.refreshLocalCache();
    this.loadCustomers();

    const p = this.sessionService.profile();
    if (p) {
      this.isCustomer = p.role === APP_ROLES.CUSTOMER;
      this.isReceiver = p.role === APP_ROLES.RECEIVER;
      this.isAdmin = p.role === APP_ROLES.ADMIN;
      this.isSupervisor = p.role === APP_ROLES.SUPERVISOR;
      this.customerScopeId =
        p.role === APP_ROLES.CUSTOMER && p.customerId ? p.customerId : null;
    }

    this.subs.add(
      this.customerRepo.changes$.subscribe(() => this.loadCustomers()),
    );

    this.subs.add(
      combineLatest([
        toObservable(this.irService.reports, { injector: this.injector }),
        this.snRepo.changes$.pipe(startWith(null)),
        this.childReportRepo.changes$.pipe(startWith(null)),
      ]).subscribe(([reports]) => {
        const scopedReports = this.customerScopeId
          ? reports.filter((r) => r.customerId === this.customerScopeId)
          : reports;

        this.computeStats(scopedReports);
        this.computeCustomerKpis(scopedReports);
        if (this.isCustomer) {
          void this.computeChildReports(scopedReports);
        }
        if (!this.isCustomer) {
          this.computeValidations(scopedReports);
        }
      }),
    );
  }

  ngOnDestroy() {
    this.subs.unsubscribe();
    this.clearReflowTimers();
  }

  /**
   * Apply a discrete status-filter change through the fade-before-reflow.
   * Called only from the customer document filter cells; the ops status
   * <select> keeps its plain [(ngModel)] binding, so ops is unaffected.
   */
  applyStatusFilter(value: string) {
    if (this.statusFilter === value) return;
    this.runReflow(() => (this.statusFilter = value));
  }

  /** Apply a discrete sort change through the same choreography. */
  applySort(value: 'updatedAt' | 'poNumber' | 'status') {
    if (this.sortBy === value) return;
    this.runReflow(() => (this.sortBy = value));
  }

  private clearReflowTimers() {
    this.reflowTimers.forEach((t) => clearTimeout(t));
    this.reflowTimers = [];
  }

  /** Duration token (`--duration-fast`) in ms, so the JS timing tracks the CSS. */
  private motionFastMs(): number {
    if (typeof window === 'undefined') return 220;
    const raw = getComputedStyle(document.documentElement)
      .getPropertyValue('--duration-fast')
      .trim();
    const n = parseFloat(raw);
    return Number.isFinite(n) && n > 0 ? n : 220;
  }

  private prefersReducedMotion(): boolean {
    return (
      typeof window !== 'undefined' &&
      window.matchMedia?.('(prefers-reduced-motion: reduce)').matches === true
    );
  }

  private runReflow(apply: () => void) {
    // Reduced motion (or no window): apply instantly, no choreography.
    if (this.prefersReducedMotion()) {
      apply();
      this.listPhase.set('idle');
      this.cdr.markForCheck();
      return;
    }
    this.clearReflowTimers();
    const d = this.motionFastMs();
    this.listPhase.set('out');
    this.reflowTimers.push(
      setTimeout(() => {
        apply();
        this.listPhase.set('in');
        this.cdr.markForCheck();
        this.reflowTimers.push(
          setTimeout(() => {
            this.listPhase.set('idle');
            this.cdr.markForCheck();
          }, d),
        );
      }, d),
    );
  }

  private async loadCustomers() {
    const list = await this.customerRepo.list();
    this.customers.set(list);
  }

  private async computeStats(reports: LocalInspectionReport[]) {
    const newStats: Record<
      string,
      { serialCount: number; serialValues: string[] }
    > = {};
    for (const r of reports) {
      // Only fetch serials for reports in the current scope
      const serials = await this.snRepo.listByReportId(r.id);
      newStats[r.id] = {
        serialCount: serials.length,
        serialValues: serials.map((s) => s.value.toLowerCase()),
      };
    }
    this.reportStatsCache = newStats;
    // We need to trigger change detection here if Angular isn't picking up the async mutation to the cache
    // But since this is called from an observable subscription, it should be fine. Just to be safe, we re-assign the object reference
    this.reportStatsCache = { ...newStats };
    this.cdr.markForCheck();
  }

  private async computeChildReports(reports: LocalInspectionReport[]) {
    const ids = new Set(reports.map((r) => r.id));
    const byReport: Record<string, LocalChildReport[]> = {};
    for (const cr of await this.childReportRepo.list()) {
      if (!ids.has(cr.inspectionReportId)) continue;
      (byReport[cr.inspectionReportId] ||= []).push(cr);
    }
    this.childReportsByReport.set(byReport);
  }

  getChildReports(reportId: string): LocalChildReport[] {
    return this.childReportsByReport()[reportId] ?? [];
  }

  /** Customer-facing label for a child report's type. */
  childTypeLabel(type: string): string {
    switch (type) {
      case 'REWORK':
        return 'Rework';
      case 'SCRAP':
        return 'Scrap';
      case 'HOLD':
        return 'Hold';
      default:
        return type;
    }
  }

  childStatusLabel(status: string): string {
    return status.replace(/_/g, ' ');
  }

  private computeCustomerKpis(reports: LocalInspectionReport[]) {
    this.kpiTotalReports = reports.length;
    this.kpiClosedReports = reports.filter((r) => r.status === 'CLOSED').length;
    this.kpiOpenReports = this.kpiTotalReports - this.kpiClosedReports;
  }

  private async computeValidations(reports: LocalInspectionReport[]) {
    // Left existing bulk fetch specifically for supervisor/inspector workflows
    const allSerials = await this.snRepo.list();

    const snByReport = allSerials.reduce(
      (acc: Record<string, LocalSerialNumber[]>, sn: LocalSerialNumber) => {
        const bucket = (acc[sn.inspectionReportId] ||= []);
        bucket.push(sn);
        return acc;
      },
      {},
    );

    const newCache: Record<string, ValidationResult> = {};
    for (const r of reports) {
      newCache[r.id] = this.validationService.validate(
        r,
        snByReport[r.id] || [],
      );
    }
    this.validationCache = newCache;
  }

  getCustomerName(id: string | null): string {
    if (!id) return 'Unknown';
    const customer = this.customers().find((c) => c.id === id);
    if (customer) return customer.name;
    // A CUSTOMER-role user has no customer list; their own name comes from the profile.
    const profile = this.sessionService.profile();
    if (profile?.customerId === id && profile.customer) {
      return profile.customer.name;
    }
    return 'Unknown customer';
  }

  /**
   * Status → badge severity for the customer document list. Mirrors the detail
   * view's `reportStatusSeverity` so a status reads the same colour on the list
   * as on the report it opens.
   */
  statusSeverity(status: string): BadgeSeverity {
    switch (status) {
      case REPORT_STATUSES.APPROVED:
      case REPORT_STATUSES.CLOSED:
        return 'success';
      case REPORT_STATUSES.ON_HOLD:
        return 'warning';
      case REPORT_STATUSES.PENDING_APPROVAL:
        return 'info';
      default:
        return 'neutral';
    }
  }

  /**
   * Whether the customer has narrowed the list (status chip, PO search, or S/N
   * search). Drives the empty state: "nothing matches your filter" vs. the
   * first-run "no reports yet". Sort is not a narrowing control, so it's excluded.
   */
  // ---- Permanent report delete (ADMIN only; the API refuses every other role) ----

  /** Report id currently being deleted, so its button shows progress. */
  public deletingId = signal<string | null>(null);

  deleteBlockedReason(report: LocalInspectionReport): string | null {
    return this.deleteFlow.blockedReason(report);
  }

  async deleteReport(
    report: LocalInspectionReport,
    event: Event,
  ): Promise<void> {
    // The row itself is a link to the report; the button must not open it.
    event.stopPropagation();
    event.preventDefault();
    if (this.deletingId()) return;
    this.deletingId.set(report.id);
    try {
      // Serials are checked too: unsynced serial work would be lost with the report.
      const serials = await this.snRepo.listByReportId(report.id);
      await this.deleteFlow.run(report, serials);
    } catch (error) {
      this.toast.showError((error as Error).message, 'Report not deleted');
    } finally {
      this.deletingId.set(null);
    }
  }

  hasActiveCustomerFilter(): boolean {
    const q = this.qFilter.trim();
    const sn = this.snFilter.trim();
    return !!this.statusFilter || q.length >= 2 || sn.length >= 2;
  }

  getFilteredReports(reports: LocalInspectionReport[]) {
    const filtered = reports.filter((r) => {
      // Safety: always scope CUSTOMER users to their own customerId in case
      // stale IndexedDB data from another customer is present
      if (this.customerScopeId && r.customerId !== this.customerScopeId) {
        return false;
      }

      let matchStatus = true;
      if (this.statusFilter === 'OPEN') {
        matchStatus = r.status !== 'CLOSED';
      } else if (this.statusFilter) {
        matchStatus = r.status === this.statusFilter;
      }

      const matchCustomer = this.customerFilter
        ? r.customerId === this.customerFilter
        : true;
      const matchQ =
        this.qFilter && this.qFilter.trim().length >= 2
          ? r.poNumber.toLowerCase().includes(this.qFilter.trim().toLowerCase())
          : true;

      let matchSn = true;
      if (this.snFilter && this.snFilter.trim().length >= 2) {
        const stats = this.reportStatsCache[r.id];
        const query = this.snFilter.trim().toLowerCase();
        matchSn = stats
          ? stats.serialValues.some((val) => val.includes(query))
          : false;
      }
      return matchStatus && matchCustomer && matchQ && matchSn;
    });

    return filtered.sort((a, b) => {
      const valA = a[this.sortBy as keyof LocalInspectionReport] as
        string | number | undefined;
      const valB = b[this.sortBy as keyof LocalInspectionReport] as
        string | number | undefined;

      if (this.sortBy === 'updatedAt') {
        const timeA = a.updatedAt ? new Date(a.updatedAt).getTime() : 0;
        const timeB = b.updatedAt ? new Date(b.updatedAt).getTime() : 0;
        if (timeA !== timeB) return timeB - timeA; // Descending
      } else {
        const strA = (valA || '').toString().toLowerCase();
        const strB = (valB || '').toString().toLowerCase();
        if (strA < strB) return -1;
        if (strA > strB) return 1;
      }

      // Tie-breakers
      if (a.poNumber !== b.poNumber)
        return a.poNumber.localeCompare(b.poNumber);
      return a.id.localeCompare(b.id);
    });
  }
}

import { Component, inject, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { SessionService } from '@portal/core/auth/services/session.service';
import { RoleLandingService } from '@portal/core/auth/services/role-landing.service';

@Component({
  selector: 'app-landing',
  standalone: true,
  template: '',
})
export class LandingComponent implements OnInit {
  private session = inject(SessionService);
  private router = inject(Router);
  private roleLanding = inject(RoleLandingService);

  ngOnInit() {
    if (!this.session.isAuthenticated()) {
      this.router.navigate(['/login']);
      return;
    }

    if (this.session.mustChangePassword()) {
      this.router.navigate(['/change-password']);
      return;
    }

    // Fallback to RoleLandingService for the proper redirect
    const currentRole = this.session.profile()?.role;

    if (currentRole) {
      this.router.navigate(this.roleLanding.getLandingRoute(currentRole));
    } else {
      this.router.navigate(['/login']);
    }
  }
}

import { CommonModule } from '@angular/common';
import { HttpClient } from '@angular/common/http';
import { Component, OnInit, computed, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { RouterModule } from '@angular/router';
import { firstValueFrom } from 'rxjs';
import { environment } from '@app-env/environment';
import { ReportTimelineComponent } from './report-timeline.component';
import {
  ReportTimelineSummary,
  STAGE_ORDER,
  TimelineEvent,
  buildTimeline,
  formatDuration,
  median,
  stageLabel,
} from './report-timeline';

/** `GET /metrics/reports` — one row per report with its raw status events. */
export interface ReportTimelineDto {
  id: string;
  reportNumber: string | null;
  poNumber: string;
  status: string;
  templateKey: string;
  customerName: string | null;
  serialCount: number;
  createdAt: string;
  events: { status: string; at: string }[];
}

export interface MetricsRow extends ReportTimelineDto {
  label: string;
  events: TimelineEvent[];
  timeline: ReportTimelineSummary;
  /** Turnaround when completed, else time so far (for sorting / display). */
  duration: number | null;
  slowest: { status: string; duration: number } | null;
}

type Period = '30' | '90' | '365' | 'all';
type SortKey = 'newest' | 'turnaround' | 'slowest';

/**
 * Admin Metrics: operational timing across every report in the tenant, plus a
 * per-report timeline. All durations are derived client-side from the transition log.
 */
@Component({
  selector: 'app-admin-metrics',
  standalone: true,
  imports: [CommonModule, FormsModule, RouterModule, ReportTimelineComponent],
  templateUrl: './admin-metrics.component.html',
})
export class AdminMetricsComponent implements OnInit {
  private readonly http = inject(HttpClient);

  public readonly loading = signal(true);
  public readonly error = signal('');
  private readonly reports = signal<MetricsRow[]>([]);

  public readonly customerFilter = signal('');
  public readonly period = signal<Period>('90');
  public readonly search = signal('');
  public readonly sort = signal<SortKey>('newest');
  public readonly selectedId = signal<string | null>(null);

  protected readonly formatDuration = formatDuration;
  protected readonly stageLabel = stageLabel;

  public readonly customers = computed(() =>
    [
      ...new Set(
        this.reports()
          .map((r) => r.customerName)
          .filter((n): n is string => !!n),
      ),
    ].sort(),
  );

  public readonly filtered = computed<MetricsRow[]>(() => {
    const customer = this.customerFilter();
    const q = this.search().trim().toLowerCase();
    const period = this.period();
    const since =
      period === 'all' ? null : Date.now() - Number(period) * 86_400_000;
    const rows = this.reports().filter(
      (r) =>
        (!customer || r.customerName === customer) &&
        (since === null || new Date(r.createdAt).getTime() >= since) &&
        (!q ||
          r.label.toLowerCase().includes(q) ||
          r.poNumber.toLowerCase().includes(q)),
    );
    const by = this.sort();
    return [...rows].sort((a, b) => {
      if (by === 'turnaround') return (b.duration ?? -1) - (a.duration ?? -1);
      if (by === 'slowest')
        return (b.slowest?.duration ?? -1) - (a.slowest?.duration ?? -1);
      return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
    });
  });

  public readonly kpis = computed(() => {
    const rows = this.filtered();
    const turnarounds = rows
      .map((r) => r.timeline.turnaround)
      .filter((t): t is number => t !== null);
    const avg =
      turnarounds.length > 0
        ? turnarounds.reduce((s, t) => s + t, 0) / turnarounds.length
        : null;
    return {
      total: rows.length,
      completed: turnarounds.length,
      inProgress: rows.filter(
        (r) => r.timeline.turnaround === null && r.timeline.receivedAt,
      ).length,
      onHold: rows.filter((r) => r.status === 'ON_HOLD').length,
      medianTurnaround: median(turnarounds),
      avgTurnaround: avg,
      serials: rows.reduce((s, r) => s + r.serialCount, 0),
    };
  });

  /** Average time a report spends in each stage (across reports that passed through it). */
  public readonly stageAverages = computed(() => {
    const sums = new Map<string, { total: number; count: number }>();
    for (const r of this.filtered()) {
      const perReport = new Map<string, number>();
      for (const s of r.timeline.stages) {
        perReport.set(s.status, (perReport.get(s.status) ?? 0) + s.duration);
      }
      for (const [status, d] of perReport) {
        const acc = sums.get(status) ?? { total: 0, count: 0 };
        acc.total += d;
        acc.count += 1;
        sums.set(status, acc);
      }
    }
    const rows = STAGE_ORDER.filter((s) => sums.has(s)).map((status) => {
      const acc = sums.get(status) ?? { total: 0, count: 1 };
      return { status, avg: acc.total / acc.count, reports: acc.count };
    });
    const max = Math.max(0, ...rows.map((r) => r.avg));
    return rows.map((r) => ({ ...r, share: max > 0 ? r.avg / max : 0 }));
  });

  public readonly selected = computed(
    () => this.filtered().find((r) => r.id === this.selectedId()) ?? null,
  );

  async ngOnInit(): Promise<void> {
    await this.load();
  }

  public async load(): Promise<void> {
    this.loading.set(true);
    this.error.set('');
    try {
      const data = await firstValueFrom(
        this.http.get<ReportTimelineDto[]>(
          `${environment.apiUrl}/metrics/reports`,
        ),
      );
      this.reports.set(data.map((d) => toRow(d)));
    } catch {
      this.error.set(
        'Metrics could not be loaded. They need a connection to the server.',
      );
    } finally {
      this.loading.set(false);
    }
  }

  public select(id: string): void {
    this.selectedId.set(this.selectedId() === id ? null : id);
  }
}

export function toRow(d: ReportTimelineDto): MetricsRow {
  const events: TimelineEvent[] = d.events.map((e, i) => ({
    id: `${d.id}-${i}`,
    status: e.status,
    at: e.at,
  }));
  const timeline = buildTimeline(events);
  const slowest = timeline.stages.reduce<{
    status: string;
    duration: number;
  } | null>(
    (best, s) =>
      !best || s.duration > best.duration
        ? { status: s.status, duration: s.duration }
        : best,
    null,
  );
  return {
    ...d,
    label: d.reportNumber || d.id.substring(0, 8).toUpperCase(),
    events,
    timeline,
    duration: timeline.turnaround ?? timeline.elapsed,
    slowest,
  };
}

import {
  afterNextRender,
  Component,
  computed,
  ElementRef,
  inject,
  Injector,
  OnInit,
  signal,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import {
  AdminTemplatesService,
  ChildReportTypeChoice,
  DefineTemplateDto,
  ExtractedToken,
  FieldRole,
  isTemplateDefined,
  OpsFieldType,
  OpsTokenField,
  SignatureSigner,
  StoredDefinition,
} from '@portal/features/templates/services/admin-templates.service';
import {} from '@portal/features/templates/schemas/definition-to-form-schema';
import { ToastService } from '@portal/shared/toast/toast.service';

/**
 * Phase D — the Define-Template wizard, reshaped to a fixed FOUR-step flow that mirrors
 * how a workbook is actually structured:
 *
 *   Detect Tokens → Metadata → Serial → Review & Save.
 *
 * Every template now has a repeating serial region (there is no flat authoring here), so
 * the old Layout/Region steps and the `hasRepeatingRows` discriminator are gone. SCOPE is
 * DERIVED from which step claims a token: a token included on the Header step exports as a
 * `header` field; every other token is a `serial` (`item`) field. The serial's own token —
 * the one whose value is the serial NUMBER written into each repeating row — is designated
 * by a per-token ROLE (`serialNumber`) rather than a separate marker picker, exactly as the
 * three header roles (inspector/supervisor/inspectionDate) designate system-owned header
 * fields. `buildDto` reads the `serialNumber`-roled token and sends it as `region.marker`.
 *
 * SUBMIT-AND-SURFACE is unchanged: the server gate is the sole authority on the semantic
 * checks; the only client niceties are per-step validity predicates (ONE source of truth)
 * that gate "Next" and that `submit()` reuses.
 *
 * ZONELESS: async-set state (the token load, the submit result) is held in SIGNALS so the
 * scheduler re-renders when it settles. The `[(ngModel)]` row fields stay plain — they
 * change through DOM events, which already notify the zoneless scheduler; the derived row
 * lists are METHODS (not computeds) so they reflect in-place ngModel edits on every CD pass.
 */

/** The repeating region's id — an internal constant (the API ignores `region.id`). */
const REGION_ID = 'serials';

const FIELD_TYPES: OpsFieldType[] = [
  'text',
  'number',
  'boolean',
  'select',
  'date',
];

/** A HEADER field may also be a `signature` (a per-report signer's picture); a serial field
 *  may not — a signature is per report, never per serial (server check `signature-header-scope`). */
const HEADER_FIELD_TYPES: OpsFieldType[] = [...FIELD_TYPES, 'signature'];

/** Who may be declared as a signature field's signer. */
export const SIGNER_OPTIONS: { value: SignatureSigner; label: string }[] = [
  { value: 'CUSTOMER', label: 'Customer (draws it once approved)' },
  { value: 'SUPERVISOR', label: 'Supervisor (account signature at approval)' },
];

/** The child report types a rework rule may upsert (mirrors the API's ChildReportType). */
const CHILD_REPORT_TYPES: ChildReportTypeChoice[] = ['REWORK', 'SCRAP', 'HOLD'];

/** The system roles a HEADER field may carry, shown in the Header step's Role select. All
 *  seven are MANDATORY: a definition cannot be saved until every one is mapped to a token (the
 *  server enforces the same via check 4c `roles-mandatory`). `inspectorSignature` marks where
 *  the inspector's account signature is placed at export — ops picks the token name. */
export const HEADER_ROLE_OPTIONS: { value: FieldRole; label: string }[] = [
  { value: 'customer', label: 'Customer' },
  { value: 'reportNumber', label: 'Report number' },
  { value: 'poNumber', label: 'PO number' },
  { value: 'inspector', label: 'Inspector' },
  { value: 'supervisor', label: 'Supervisor' },
  { value: 'inspectionDate', label: 'Inspection date' },
  { value: 'inspectorSignature', label: 'Inspector signature' },
];

/** One trigger-field choice for the rework rule (see the region-mode dropdown). */
export interface TriggerFieldOption {
  key: string;
  label: string;
}

/**
 * One row of the describe state — one per extracted token. A token is claimed by AT MOST
 * one step: `header` true → a header field; otherwise it is a serial candidate and `serial`
 * governs inclusion. `role` is the per-token system role ('' = none).
 */
export interface DescribeRow {
  token: string;
  cell: string;
  /** The workbook row the token sits on (kept from detection; not rendered). */
  row: number;
  /** Included as a HEADER field. When true the token is not a serial candidate. */
  header: boolean;
  /** Included as a SERIAL (item) field. Meaningful only when `header` is false. */
  serial: boolean;
  label: string;
  type: OpsFieldType;
  required: boolean;
  section: string;
  /** Comma-separated choices; only meaningful when `type === 'select'`. */
  optionsText: string;
  /** '' = no role. A header role (Header step) or `serialNumber` (Serial step). */
  role: FieldRole | '';
  /** Who signs a `signature` field ('' until chosen; meaningless for any other type). */
  signer: SignatureSigner | '';
}

export type WizardStepKey = 'detect' | 'header' | 'serial' | 'review';

export interface WizardStep {
  key: WizardStepKey;
  label: string;
}

/** The fixed four-step sequence — no dynamic/optional steps any more. */
const STEPS: WizardStep[] = [
  { key: 'detect', label: 'Detect Tokens' },
  { key: 'header', label: 'Metadata' },
  { key: 'serial', label: 'Serial' },
  { key: 'review', label: 'Review & Save' },
];

@Component({
  selector: 'app-template-define',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './template-define.component.html',
})
export class TemplateDefineComponent implements OnInit {
  private templatesService = inject(AdminTemplatesService);
  private route = inject(ActivatedRoute);
  private router = inject(Router);
  private toast = inject(ToastService);
  private injector = inject(Injector);
  private readonly host = inject(ElementRef<HTMLElement>);

  public readonly fieldTypes = FIELD_TYPES;
  public readonly headerFieldTypes = HEADER_FIELD_TYPES;
  public readonly signerOptions = SIGNER_OPTIONS;
  public readonly childReportTypes = CHILD_REPORT_TYPES;
  public readonly headerRoleOptions = HEADER_ROLE_OPTIONS;
  public readonly steps = STEPS;

  public templateId = '';

  // Async-set: a SIGNAL so the zoneless scheduler re-renders when the token load settles.
  public readonly rows = signal<DescribeRow[]>([]);

  // Save-time metadata + rework trigger — plain [(ngModel)] (event-driven; the scheduler is
  // already notified by the DOM event, and two-way binding needs a plain field).
  public displayName = '';
  public reworkEnabled = false;
  public reworkField = '';
  public reworkEquals = '';
  public reworkChildType: ChildReportTypeChoice = 'REWORK';
  public reworkSuffix = '';

  // Bulk-action inputs for the Serial step (apply Type / Section across the included rows).
  public bulkType: OpsFieldType = 'text';
  public bulkSection = '';

  // Once the author deliberately changes any serial row's role, the wizard stops
  // auto-defaulting the serialNumber marker (their choice wins).
  private markerTouched = false;

  // READ-ONLY recap mode. A defined template (definitionJson already saved) opens straight
  // to the recap with no route into the authoring steps — re-definition is a hard block
  // (#6). A signal because it is set after the async load settles (zoneless: the write
  // schedules the CD pass that renders the recap); the recap's data derives from the same
  // `rows()` signal + scalar fields that authoring uses, hydrated from the STORED definition.
  public readonly readOnly = signal(false);

  // UI state (signals — set after async work, read by the template).
  public readonly isLoading = signal(true);
  public readonly isSubmitting = signal(false);
  public readonly loadError = signal('');
  public readonly submitError = signal('');
  public readonly failedCheck = signal('');
  public readonly success = signal(false);
  /** Set when the version was rejected by an admin: the reason shown above the wizard. */
  public readonly rejectionReason = signal<string | null>(null);
  /** Set when the wizard was pre-filled from an earlier version (its version number). */
  public readonly prefilledFromVersion = signal<number | null>(null);

  // ---------------------------------------------------------------------------
  // Wizard navigation — a fixed four-step sequence.
  // ---------------------------------------------------------------------------

  public readonly currentStep = signal(0);

  public readonly activeStep = computed<WizardStep>(() => {
    const i = Math.min(Math.max(this.currentStep(), 0), STEPS.length - 1);
    // The clamped index is always in range; the fallback is only for the type checker
    // (noUncheckedIndexedAccess). STEPS always starts with `detect`.
    return STEPS[i] ?? { key: 'detect', label: 'Detect Tokens' };
  });

  public readonly isFirstStep = computed(() => this.currentStep() === 0);
  public readonly isLastStep = computed(
    () => this.currentStep() >= STEPS.length - 1,
  );

  async ngOnInit(): Promise<void> {
    this.templateId = this.route.snapshot.paramMap.get('id') ?? '';
    await this.load();
  }

  public async load(): Promise<void> {
    this.isLoading.set(true);
    this.loadError.set('');
    try {
      // #6 — decide defined-vs-undefined FIRST, from the authoritative stored definition
      // (server read), not from a re-extracted-token guess. A defined template becomes a
      // read-only recap hydrated from what was SAVED; an undefined one keeps today's full
      // authoring flow, unchanged.
      const detail = await this.templatesService.getDefinition(this.templateId);
      this.rejectionReason.set(
        detail.approvalStatus === 'REJECTED'
          ? (detail.rejectionReason ?? '')
          : null,
      );
      this.prefilledFromVersion.set(null);
      if (
        this.isDefined(detail.definitionJson) &&
        detail.approvalStatus !== 'REJECTED'
      ) {
        this.hydrateFromDefinition(detail.definitionJson);
        // Signal write LAST — flips the view to the recap and schedules the CD pass that
        // renders it (also flushing the scalar fields hydrateFromDefinition set).
        this.readOnly.set(true);
      } else {
        const tokens = await this.templatesService.getTokens(this.templateId);
        const rows = this.toRows(tokens);
        this.markerTouched = false;
        // A rejected version is edited from its own stored definition; a fresh upgrade
        // pre-fills from the previous version (matching tokens only).
        if (this.isDefined(detail.definitionJson)) {
          this.prefillRows(rows, detail.definitionJson);
        } else if (detail.previousDefinition) {
          this.prefillRows(rows, detail.previousDefinition.definitionJson);
          this.prefilledFromVersion.set(
            detail.previousDefinition.templateVersion,
          );
        }
        this.rows.set(rows);
        this.ensureSerialMarkerDefault();
        this.readOnly.set(false);
      }
    } catch (e: unknown) {
      this.loadError.set(
        this.errorMessage(e, 'Failed to load template tokens. Are you online?'),
      );
    } finally {
      this.isLoading.set(false);
    }
  }

  /**
   * DEFINED-STATE detection (#6.1). The stored `definitionJson` is the API's built
   * CandidateDefinition; a real definition always carries at least one field (the engine
   * rejects an empty one at the gate). We test the actual shape — a non-empty `fields[]` —
   * rather than trusting a bare truthy check, so an empty/garbled `{}` still reads as
   * undefined and falls through to authoring.
   */
  private isDefined(def: StoredDefinition | null): def is StoredDefinition {
    return isTemplateDefined(def);
  }

  /**
   * Reverse-map a STORED definition into the wizard's describe rows + scalar state, so the
   * recap reflects exactly what was saved — roles, labels, marker, rework, scope — and never
   * re-infers from the workbook's current tokens (fidelity: if the file changed under a saved
   * definition, we show the saved definition). Scope is the source of truth for header-vs-
   * serial; the serial marker's EXACT token comes from `export.regions` (source `rowSerial`),
   * which is more precise than reconstructing it from the field key.
   */
  private hydrateFromDefinition(def: StoredDefinition): void {
    const markerToken = this.markerTokenFromExport(def);
    const rows: DescribeRow[] = (def.fields ?? []).map((f) => {
      const isMarker = f.role === 'serialNumber';
      return {
        token: isMarker && markerToken ? markerToken : `{{${f.key}}}`,
        cell: '',
        row: 0,
        header: f.scope === 'header',
        serial: f.scope === 'item',
        label: f.label ?? '',
        type: f.type ?? 'text',
        required: !!f.required,
        section: f.section ?? '',
        optionsText: Array.isArray(f.options) ? f.options.join(', ') : '',
        role: f.role ?? '',
        signer: f.signer ?? '',
      };
    });
    this.rows.set(rows);
    this.displayName = def.displayName ?? '';
    this.hydrateRework(def);
  }

  /**
   * Copy a stored definition onto freshly-extracted rows, for every token the two share
   * (matched by field key, or the serial marker's exact token). Tokens new to this workbook
   * stay as untouched defaults for the author to describe; tokens that left it are dropped.
   * Also carries the display name and the rework rule when its trigger field survives.
   */
  private prefillRows(rows: DescribeRow[], def: StoredDefinition): void {
    const markerToken = this.markerTokenFromExport(def);
    const byKey = new Map((def.fields ?? []).map((f) => [f.key, f]));
    const strip = (t: string) =>
      t.replace(/^\{\{\s*/, '').replace(/\s*\}\}$/, '');
    let matched = 0;
    for (const row of rows) {
      const field =
        byKey.get(strip(row.token)) ??
        (markerToken && row.token === markerToken
          ? (def.fields ?? []).find((f) => f.role === 'serialNumber')
          : undefined);
      if (!field) continue;
      matched++;
      row.header = field.scope === 'header';
      row.serial = field.scope === 'item';
      row.label = field.label ?? '';
      row.type = field.type ?? 'text';
      row.required = !!field.required;
      row.section = field.section ?? '';
      row.optionsText = Array.isArray(field.options)
        ? field.options.join(', ')
        : '';
      row.role = field.role ?? '';
      row.signer = field.signer ?? '';
      if (field.role === 'serialNumber') this.markerTouched = true;
    }
    if (matched === 0) return;
    this.displayName = def.displayName ?? '';
    this.hydrateRework(def);
    if (
      this.reworkEnabled &&
      !rows.some((r) => strip(r.token) === this.reworkField)
    ) {
      this.reworkEnabled = false;
      this.reworkField = '';
    }
  }

  /** The serial marker's exact token, read back from the stored export (the `rowSerial`
   *  entry in the region's export list) — the marker's token is stored there, not on the
   *  field itself. Undefined if the definition carries no such entry. */
  private markerTokenFromExport(def: StoredDefinition): string | undefined {
    const regionId = def.regions?.[0]?.id ?? REGION_ID;
    const byRegion = def.export?.regions?.[regionId];
    const entry =
      byRegion?.find((e) => e.source === 'rowSerial') ?? byRegion?.[0];
    return entry?.token;
  }

  /** Reverse-map the stored rework rule (`rules[0]`, the interpreter's `when`/`then` shape)
   *  back onto the recap's scalar fields. Absent/malformed → no rule. */
  private hydrateRework(def: StoredDefinition): void {
    const rule = Array.isArray(def.rules) ? def.rules[0] : undefined;
    const r = (rule ?? {}) as {
      when?: { field?: string; value?: unknown };
      then?: { childType?: string; reportNumberSuffix?: string };
    };
    const field = r.when?.field;
    const childType = r.then?.childType;
    if (!field || !childType) {
      this.reworkEnabled = false;
      return;
    }
    this.reworkEnabled = true;
    this.reworkField = field;
    this.reworkEquals = r.when?.value == null ? '' : String(r.when.value);
    this.reworkChildType = CHILD_REPORT_TYPES.includes(
      childType as ChildReportTypeChoice,
    )
      ? (childType as ChildReportTypeChoice)
      : 'REWORK';
    this.reworkSuffix = r.then?.reportNumberSuffix ?? '';
  }

  /**
   * De-dupe the token list (a token can appear in multiple cells) into one row each. Every
   * token starts as a SERIAL candidate (pre-checked). The `serialNumber` marker default is
   * applied separately (ensureSerialMarkerDefault) so it always lands on the first token
   * still UNCLAIMED by Header, even after the author moves tokens into the header set.
   */
  private toRows(tokens: ExtractedToken[]): DescribeRow[] {
    const seen = new Set<string>();
    const rows: DescribeRow[] = [];
    for (const t of tokens) {
      if (seen.has(t.token)) continue;
      seen.add(t.token);
      rows.push({
        token: t.token,
        cell: t.cell,
        row: t.row,
        header: false,
        serial: true,
        label: '',
        type: 'text',
        required: false,
        section: '',
        optionsText: '',
        role: '',
        signer: '',
      });
    }
    return rows;
  }

  /**
   * Default the `serialNumber` marker to the FIRST included serial field, unless the author
   * has already taken over (markerTouched) or a marker is already set. Run at load and on
   * entering the Serial step, so claiming the first token into Header re-homes the default
   * onto the next unclaimed token rather than silently leaving no marker.
   */
  private ensureSerialMarkerDefault(): void {
    if (this.markerTouched) return;
    const serials = this.serialRows();
    if (serials.length === 0) return;
    if (serials.some((r) => r.role === 'serialNumber')) return;
    const first = serials[0];
    if (!first) return;
    first.role = 'serialNumber';
    first.type = 'text';
    first.required = false;
  }

  public clearSubmitFeedback(): void {
    this.submitError.set('');
    this.failedCheck.set('');
  }

  // ---------------------------------------------------------------------------
  // Derived row lists — METHODS (reflect in-place ngModel edits every CD pass).
  // ---------------------------------------------------------------------------

  /** Every token — the Header step's grid iterates this. */
  public allRows(): DescribeRow[] {
    return this.rows();
  }

  /** Tokens claimed as HEADER fields. */
  public headerRows(): DescribeRow[] {
    return this.rows().filter((r) => r.header);
  }

  /** Tokens not claimed by Header — the Serial step's grid iterates this. */
  public serialCandidateRows(): DescribeRow[] {
    return this.rows().filter((r) => !r.header);
  }

  /** The included SERIAL (item) fields — what buildDto emits and validity checks. */
  public serialRows(): DescribeRow[] {
    return this.rows().filter((r) => !r.header && r.serial);
  }

  /** The serial row carrying the `serialNumber` role — its token is `region.marker`. */
  public serialMarkerRow(): DescribeRow | undefined {
    return this.serialRows().find((r) => r.role === 'serialNumber');
  }

  public allSerialSelected(): boolean {
    const candidates = this.serialCandidateRows();
    return candidates.length > 0 && candidates.every((r) => r.serial);
  }

  // ---------------------------------------------------------------------------
  // Include / role / bulk mutations.
  // ---------------------------------------------------------------------------

  /** Header-include toggle: claiming a token for Header removes it from the serial set and
   *  drops any role that no longer fits the new scope. Un-claiming returns it as a
   *  pre-checked serial candidate. */
  public onHeaderToggle(row: DescribeRow, checked: boolean): void {
    row.header = checked;
    if (checked) {
      row.serial = false;
      if (row.role === 'serialNumber') row.role = '';
    } else {
      row.serial = true;
      // Leaving Header: a header role no longer applies, nor does a signature (header-only).
      if (row.role && row.role !== 'serialNumber') row.role = '';
      if (row.type === 'signature') this.resetSignature(row);
    }
    this.clearSubmitFeedback();
  }

  /** Type select handler (header step): a signature starts with its signer unset (the author
   *  must choose), and leaving `signature` drops the signer. */
  public onTypeChange(row: DescribeRow): void {
    if (row.type !== 'signature') row.signer = '';
    this.clearSubmitFeedback();
  }

  /** Signer select handler: a customer signature is always required, so the flag is forced. */
  public onSignerChange(row: DescribeRow): void {
    if (row.signer === 'CUSTOMER') row.required = true;
    this.clearSubmitFeedback();
  }

  /** A signature the customer signs — implicitly required, so its Required toggle is hidden. */
  public isCustomerSignature(row: DescribeRow): boolean {
    return row.type === 'signature' && row.signer === 'CUSTOMER';
  }

  /** A signature field was demoted out of Header — back to plain text, signer cleared. */
  private resetSignature(row: DescribeRow): void {
    row.type = 'text';
    row.signer = '';
  }

  /** Whether the row is a header `signature` field (its Role/Options/Required UI differs). */
  public isSignature(row: DescribeRow): boolean {
    return row.type === 'signature';
  }

  /** Role select handler — enforces role UNIQUENESS in the UI (not just server-side) and
   *  forces the type a role implies (dates for inspectionDate, text otherwise); `required`
   *  is meaningless for a roled field. */
  public onRoleChange(row: DescribeRow): void {
    // A deliberate role change on a serial row means the author is managing the marker —
    // stop auto-defaulting it from here on.
    if (!row.header) {
      this.markerTouched = true;
    }
    if (row.role) {
      for (const other of this.rows()) {
        if (other !== row && other.role === row.role) other.role = '';
      }
      row.type = row.role === 'inspectionDate' ? 'date' : 'text';
      row.required = false;
      row.signer = '';
    }
    this.clearSubmitFeedback();
  }

  public isRoled(row: DescribeRow): boolean {
    return row.role !== '';
  }

  /**
   * #1 — the header roles offered in a given row's Role select: every role NOT already
   * assigned to ANOTHER header field, PLUS this row's own current role (so it stays shown
   * and selectable). Role uniqueness is already enforced on change (onRoleChange), but
   * hiding taken roles up front keeps the dropdown honest — an author never picks a role
   * that would silently steal it from another field. A METHOD (not a computed) so it
   * reflects in-place ngModel role edits on every CD pass, matching the other row-derived
   * lists (zoneless-safe: the row state IS the source, no post-await signal write).
   */
  public availableHeaderRoleOptions(
    row: DescribeRow,
  ): { value: FieldRole; label: string }[] {
    const takenElsewhere = new Set(
      this.headerRows()
        .filter((r) => r !== row)
        .map((r) => r.role)
        .filter((role): role is FieldRole => role !== ''),
    );
    return HEADER_ROLE_OPTIONS.filter(
      (opt) => opt.value === row.role || !takenElsewhere.has(opt.value),
    );
  }

  public onSelectAllSerial(checked: boolean): void {
    for (const r of this.serialCandidateRows()) r.serial = checked;
    this.clearSubmitFeedback();
  }

  /** Bulk-set Type across the included serial rows (skips the roled marker — its type is
   *  forced). */
  public applyBulkType(): void {
    for (const r of this.serialRows()) {
      if (r.role) continue;
      r.type = this.bulkType;
    }
    this.clearSubmitFeedback();
  }

  /** Bulk-set Section across the included serial rows (skips the roled marker). */
  public applyBulkSection(): void {
    const section = this.bulkSection.trim();
    for (const r of this.serialRows()) {
      if (r.role) continue;
      r.section = section;
    }
    this.clearSubmitFeedback();
  }

  /** Token → data key: strip the `{{ }}`, matching the server builder's `strip`. */
  private stripToken(token: string): string {
    return token.replace(/^\{\{\s*/, '').replace(/\s*\}\}$/, '');
  }

  /**
   * The fields eligible as a rework trigger — the included SERIAL fields (what the
   * interpreter matches on), minus the `serialNumber` marker (an identity, not a datum).
   * A METHOD so it reflects in-place row edits by the time the author reaches Review.
   */
  public triggerFieldOptions(): TriggerFieldOption[] {
    return this.serialRows()
      .filter((r) => r.role !== 'serialNumber')
      .map((r) => ({
        key: this.stripToken(r.token),
        label: r.label.trim() || r.token,
      }));
  }

  // ---------------------------------------------------------------------------
  // Per-step validity — ONE source of truth (gates "Next"; `submit()` reuses these).
  // ---------------------------------------------------------------------------

  /** The six mandatory header roles (from the Role select) — every one must be mapped to an
   *  included header field before a definition can be saved. Mirrors the server's check 4c. */
  private readonly mandatoryHeaderRoles: FieldRole[] = HEADER_ROLE_OPTIONS.map(
    (o) => o.value,
  );

  /** Header roles not yet assigned to any included header field — empty means all six are
   *  mapped. A METHOD so it reflects in-place role edits every CD pass (zoneless-safe: no
   *  post-await signal write, the row state IS the source). */
  public missingHeaderRoles(): FieldRole[] {
    const assigned = new Set(
      this.headerRows()
        .map((r) => r.role)
        .filter((role): role is FieldRole => role !== ''),
    );
    return this.mandatoryHeaderRoles.filter((role) => !assigned.has(role));
  }

  /** The human labels of the still-unassigned header roles, comma-joined — for the inline
   *  warning and the submit-time message (one source of truth for the role names). */
  public missingHeaderRoleLabels(): string {
    return this.missingHeaderRoles()
      .map(
        (role) =>
          HEADER_ROLE_OPTIONS.find((o) => o.value === role)?.label ?? role,
      )
      .join(', ');
  }

  /** Header step: every INCLUDED header field needs a label — this gates leaving the
   *  Metadata step. The all-six-roles mandate is a SAVE invariant (see `canSave`), NOT a
   *  per-step gate: an author can move between steps while still assigning roles; only the
   *  final Save (and the server's `roles-mandatory` check) requires all six. */
  public headerStepValid(): boolean {
    return this.headerRows().every(
      (r) => !!r.label.trim() && (!this.isSignature(r) || !!r.signer),
    );
  }

  /** Serial step: at least one included serial field, each with a label, and EXACTLY one
   *  `serialNumber` marker among them. */
  public serialStepValid(): boolean {
    const serial = this.serialRows();
    if (serial.length === 0) return false;
    if (!serial.every((r) => !!r.label.trim())) return false;
    return serial.filter((r) => r.role === 'serialNumber').length === 1;
  }

  public stepValid(key: WizardStepKey): boolean {
    switch (key) {
      case 'detect':
        return true;
      case 'header':
        return this.headerStepValid();
      case 'serial':
        return this.serialStepValid();
      case 'review':
        return this.canSave();
    }
  }

  public canGoNext(): boolean {
    return this.stepValid(this.activeStep().key);
  }

  public next(): void {
    if (!this.canGoNext()) return;
    if (this.currentStep() < STEPS.length - 1) {
      this.currentStep.update((s) => s + 1);
      this.onStepEntered();
    }
  }

  public prev(): void {
    if (this.currentStep() > 0) {
      this.currentStep.update((s) => s - 1);
      this.onStepEntered();
    }
  }

  /** Per-step entry hook. Landing on Serial re-homes the serialNumber marker default onto
   *  the first still-unclaimed serial field (unless the author has taken it over); every
   *  step entry also returns the page to the top so a new (often taller) step opens scrolled
   *  to its start rather than inheriting the previous step's offset. */
  private onStepEntered(): void {
    if (this.activeStep().key === 'serial') {
      this.ensureSerialMarkerDefault();
    }
    this.scrollWizardToTop();
  }

  /**
   * Return the page to the top on a step change (and on a submit failure, so the top-pinned
   * error is in view). The bounded inner `#stepBody` frame is gone — the wizard flows in
   * normal document flow and the shell's `<main id="main-content">` owns the scroll — so we
   * reset the nearest scrollable ANCESTOR of this component (that `main`), not an inner
   * element or `window`. Scheduled as POST-RENDER work (`afterNextRender`): the step swap is
   * signal-driven, so the new step's content only exists after the scheduler re-renders —
   * resetting scrollTop in that after-render hook lands on the fresh content and does not
   * fight the zoneless change-detection pass. The bound injector lets us call it from a plain
   * event handler (outside the constructor's injection context).
   */
  private scrollWizardToTop(): void {
    afterNextRender(
      () => {
        const el = this.scrollParent(this.host.nativeElement);
        if (el) el.scrollTop = 0;
      },
      { injector: this.injector },
    );
  }

  /** Walk up from `node` to the first ancestor that actually scrolls vertically (the shell's
   *  `main`), or null if none is found (e.g. an isolated test render with no scroll host). */
  private scrollParent(node: HTMLElement): HTMLElement | null {
    let cur = node.parentElement;
    while (cur) {
      const overflowY = getComputedStyle(cur).overflowY;
      if (overflowY === 'auto' || overflowY === 'scroll') return cur;
      cur = cur.parentElement;
    }
    return null;
  }

  /** The client-checkable minimum for a Save — the per-step label predicates PLUS the
   *  all-six-header-roles mandate (mirrors the server's `roles-mandatory` gate, check 4c).
   *  The SERVER gate stays the sole authority on the full semantic checks. */
  public canSave(): boolean {
    return (
      this.headerStepValid() &&
      this.serialStepValid() &&
      this.missingHeaderRoles().length === 0
    );
  }

  private toField(row: DescribeRow, scope: 'header' | 'item'): OpsTokenField {
    const field: OpsTokenField = {
      token: row.token,
      label: row.label.trim(),
      type: row.type,
      required: this.isCustomerSignature(row) ? true : row.required,
      scope,
    };
    if (row.role) {
      field.role = row.role;
    }
    if (scope === 'header' && row.type === 'signature' && row.signer) {
      field.signer = row.signer;
    }
    // Section only on plain (non-roled) serial fields — the marker has no section.
    if (scope === 'item' && !row.role && row.section.trim()) {
      field.section = row.section.trim();
    }
    if (row.type === 'select') {
      field.options = row.optionsText
        .split(',')
        .map((s) => s.trim())
        .filter((s) => s.length > 0);
    }
    return field;
  }

  /** Assemble the request body from the current form state. Pure. */
  public buildDto(): DefineTemplateDto {
    const fields: OpsTokenField[] = [
      ...this.headerRows().map((r) => this.toField(r, 'header')),
      ...this.serialRows().map((r) => this.toField(r, 'item')),
    ];

    const marker = this.serialMarkerRow();
    const dto: DefineTemplateDto = {
      fields,
      // Always a serial region now. `id` is an internal constant (the API ignores it);
      // `marker` is the `serialNumber`-roled token — the serial's own token → `rowSerial`.
      region: {
        id: REGION_ID,
        marker: marker ? marker.token : '',
      },
    };
    if (this.displayName.trim()) {
      dto.displayName = this.displayName.trim();
    }
    if (this.reworkEnabled) {
      dto.reworkRule = {
        field: this.reworkField,
        equals: this.reworkEquals.trim(),
        childType: this.reworkChildType,
      };
      // Always suffixed: a bare suffix would give the child the parent's exact number.
      dto.reworkRule.reportNumberSuffix =
        this.reworkSuffix.trim() || `_${this.reworkChildType.toLowerCase()}`;
    }
    return dto;
  }

  public async submit(): Promise<void> {
    // #6.3 — a defined template is read-only: no save path exists in this mode. Defence in
    // depth behind the hidden nav (and the server's own PUT guard); re-shaping a form means
    // uploading a new template, not re-defining this one.
    if (this.readOnly()) return;

    this.clearSubmitFeedback();
    this.success.set(false);

    // Final client-side guard — REUSES the per-step predicates (not a reimplementation of
    // the server gate) with granular messages.
    if (!this.serialStepValid()) {
      const serial = this.serialRows();
      this.submitError.set(
        serial.length === 0
          ? 'Include at least one serial field before saving.'
          : serial.filter((r) => r.role === 'serialNumber').length !== 1
            ? 'Mark exactly one serial field as the Serial Number.'
            : 'Every included serial field needs a label.',
      );
      this.scrollWizardToTop();
      return;
    }
    if (!this.headerStepValid()) {
      this.submitError.set(
        this.headerRows().some((r) => !r.label.trim())
          ? 'Every included metadata field needs a label.'
          : 'Choose who signs every signature field.',
      );
      this.scrollWizardToTop();
      return;
    }
    if (this.missingHeaderRoles().length > 0) {
      this.submitError.set(
        `Assign every system role before saving. Unassigned: ${this.missingHeaderRoleLabels()}.`,
      );
      this.scrollWizardToTop();
      return;
    }

    await this.persist();
  }

  /** The actual persist. Assumes the client-side validity guards have already passed. */
  private async persist(): Promise<void> {
    this.isSubmitting.set(true);
    try {
      await this.templatesService.defineTemplate(
        this.templateId,
        this.buildDto(),
      );
      this.success.set(true);
      // Save landed — leave the wizard for the templates list and carry the confirmation
      // there as a toast (app-level, survives the navigation), rather than stranding the
      // author on the Review step behind an inline banner.
      this.toast.showSuccess(
        'Template form saved. It can now be used for reports.',
        'Saved',
      );
      await this.navigateToList();
    } catch (e: unknown) {
      const body = (e as { error?: { check?: string; message?: string } })
        ?.error;
      this.failedCheck.set(body?.check ?? '');
      this.submitError.set(
        this.errorMessage(e, 'Failed to save the definition.'),
      );
      this.scrollWizardToTop();
    } finally {
      this.isSubmitting.set(false);
    }
  }

  public backToList(): void {
    this.navigateToList();
  }

  // Relative to the role area this page is mounted under (/admin or /supervisor):
  // Relative '..' navigation proved unreliable for this multi-segment route, so go absolute:
  // the first URL segment is the role area, and its templates list sits directly under it.
  private navigateToList(): Promise<boolean> {
    const [path = ''] = this.router.url.split(/[?#]/);
    const area = path.split('/').filter(Boolean)[0];
    return this.router.navigate(['/', area, 'templates']);
  }

  private errorMessage(e: unknown, fallback: string): string {
    const err = e as { error?: { message?: string }; message?: string };
    return err?.error?.message || err?.message || fallback;
  }
}

import { Component, inject, OnInit, ViewChild, computed } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule, NgForm } from '@angular/forms';
import { AdminUsersService } from '@portal/features/users/services/admin-users.service';
import { LocalUser, LocalCustomer } from '@portal/core/offline/models/types';
import { CustomerLocalRepo } from '@portal/core/offline/repos/customer-local.repo';
import { APP_ROLES, AppRole } from '@portal/core/constants/app.constants';
import { UserPreferencesService } from '@portal/core/services/user-preferences.service';

@Component({
  selector: 'app-admin-users',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './admin-users.component.html',
})
export class AdminUsersComponent implements OnInit {
  private usersService = inject(AdminUsersService);

  public users = this.usersService.users;
  public prefs = inject(UserPreferencesService);
  public isCompactMode = computed(() => this.prefs.preferences().compactMode);

  @ViewChild('userForm') userForm!: NgForm;

  // Form state
  public formEmail = '';
  public formName = '';
  public formRole: AppRole = APP_ROLES.RECEIVER;
  public formPassword = '';
  public formCustomerId = '';
  public formError = '';

  // Edit User Form state
  public editUserId: string | null = null;
  public editFormName = '';
  public editFormPassword = '';
  public editFormError = '';

  public customers: LocalCustomer[] = [];
  private customerRepo = inject(CustomerLocalRepo);

  public deletingIds = new Set<string>();

  constructor() {
    // legacy temp password listener can be removed or kept empty if service still emits
  }

  ngOnInit() {
    this.usersService.refreshLocalCache();
    this.loadCustomers();
  }

  private async loadCustomers() {
    this.customers = await this.customerRepo.list();
  }

  public async onSubmitCreate(): Promise<void> {
    this.formError = '';

    if (!this.formEmail) {
      this.formError = 'Email is required.';
      return;
    }

    if (!this.formPassword) {
      this.formError = 'Temporary password is required.';
      return;
    }

    if (this.formRole === APP_ROLES.CUSTOMER && !this.formCustomerId) {
      this.formError = 'Customer selection is required for Customer role.';
      return;
    }

    try {
      await this.usersService.createUser({
        email: this.formEmail.toLowerCase().trim(),
        name: this.formName || null,
        role: this.formRole,
        customerId:
          this.formRole === APP_ROLES.CUSTOMER ? this.formCustomerId : null,
        password: this.formPassword,
      });

      // Reset form state and validation
      if (this.userForm) {
        this.userForm.resetForm();
      }
      this.formEmail = '';
      this.formName = '';
      this.formPassword = '';
      this.formRole = APP_ROLES.RECEIVER;
      this.formCustomerId = '';
    } catch (e) {
      console.error(e);
      this.formError = 'Failed to save user.';
    }
  }

  public async onToggleActive(user: LocalUser): Promise<void> {
    try {
      await this.usersService.toggleActive(user);
    } catch (e) {
      console.error(e);
      this.formError = 'Failed to toggle active state.';
    }
  }

  public openEditModal(user: LocalUser): void {
    this.editUserId = user.id;
    this.editFormName = user.name || '';
    this.editFormPassword = '';
    this.editFormError = '';
  }

  public closeEditModal(): void {
    this.editUserId = null;
  }

  public async onSubmitEdit(): Promise<void> {
    this.editFormError = '';

    if (!this.editUserId) return;

    // Create optimistic copy
    const userToEdit = this.users().find((user) => user.id === this.editUserId);
    if (!userToEdit) {
      this.editFormError = 'User not found.';
      return;
    }

    try {
      await this.usersService.updateProfile(this.editUserId, {
        name: this.editFormName || null,
        password: this.editFormPassword || undefined,
      });

      this.closeEditModal();
    } catch (e) {
      console.error(e);
      this.editFormError = 'Failed to update user.';
    }
  }

  public async onDelete(user: LocalUser): Promise<void> {
    if (this.deletingIds.has(user.id)) return;

    // Start sleek inline loading
    this.deletingIds.add(user.id);
    this.formError = '';

    try {
      await this.usersService.deleteUser(user);
    } catch (e) {
      console.error(e);
      this.formError = 'Failed to delete user.';
    } finally {
      this.deletingIds.delete(user.id);
    }
  }
}

import {
  Component,
  ElementRef,
  HostListener,
  ViewChild,
  computed,
  inject,
  signal,
} from '@angular/core';
import { Router } from '@angular/router';
import { CommonModule } from '@angular/common';
import {
  NavigationEnd,
  RouterOutlet,
  RouterLink,
  RouterLinkActive,
} from '@angular/router';
import { ConnectivityService } from '@portal/core/offline/services/connectivity.service';
import { OutboxService } from '@portal/core/offline/services/outbox.service';
import { SessionService } from '@portal/core/auth/services/session.service';
import { SyncOrchestratorService } from '@portal/core/offline/services/sync-orchestrator.service';
import { NavigationService } from '@portal/core/navigation/services/navigation.service';
import { AppRoutes } from '@portal/core/navigation/constants/routes.constants';
import { environment } from '@app-env/environment';
import { AuthRequiredComponent } from '@portal/shared/components/auth-required/auth-required.component';
import { APP_ROLES } from '@portal/core/constants/app.constants';
import { SignatureService } from '@portal/core/auth/services/signature.service';
import { SignatureDialogComponent } from '@portal/shared/components/signature-dialog/signature-dialog.component';
import { ThemeToggleComponent } from '@portal/shared/components/theme-toggle/theme-toggle.component';
import { ThemeService } from '@portal/core/theme/theme.service';

@Component({
  selector: 'app-shell',
  standalone: true,
  imports: [
    CommonModule,
    RouterOutlet,
    RouterLink,
    RouterLinkActive,
    AuthRequiredComponent,
    SignatureDialogComponent,
    ThemeToggleComponent,
  ],
  templateUrl: './shell.component.html',
})
export class ShellComponent {
  private connectivity = inject(ConnectivityService);
  private outbox = inject(OutboxService);
  private session = inject(SessionService);
  private router = inject(Router);
  private orchestrator = inject(SyncOrchestratorService);
  private signatures = inject(SignatureService);
  /** Instantiated here so the customer theme is applied for the whole session. */
  public readonly theme = inject(ThemeService);
  public navigation = inject(NavigationService);

  /** Inspector with no account signature: the content is blurred and inert until one
   *  is registered (re-shown on every login/reload, like the forced password change). */
  public signatureRequired = this.session.signatureRequired;
  public signatureDialogOpen = signal(false);

  public isOnline = this.connectivity.isOnline;
  public pendingCount = this.outbox.pendingCount;
  public hasConflict = this.outbox.hasConflict;
  public isAuthenticated = this.session.isAuthenticated;
  public profile = this.session.profile;

  /** Customers are read-only and hold no local writes, so the header shows them
   *  neither the sync/connectivity status nor their role. */
  public isCustomer = computed(
    () => this.profile()?.role === APP_ROLES.CUSTOMER,
  );

  /** The organisation under the user's name: a customer sees their own company,
   *  staff see the tenant (the service company). */
  public organizationName = computed(() => {
    const p = this.profile();
    if (!p) return '';
    if (this.isCustomer()) {
      return (
        this.theme.branding()?.name || p.customer?.name || p.tenant?.name || ''
      );
    }
    return p.tenant?.name || p.customer?.name || 'Internal';
  });

  /** The signed-in customer has a logo: the header shows their brand, not OTS's. */
  public customerBrandLogo = computed(
    () => this.isCustomer() && !!this.theme.branding()?.logoId,
  );

  public syncStatus = this.orchestrator.syncStatus;
  public syncState = this.orchestrator.syncState;
  public lastSyncedAt = this.orchestrator.lastSyncedAt;
  public lastSyncError = this.orchestrator.lastSyncError;

  public canSyncNow = computed(
    () =>
      this.isAuthenticated() &&
      this.isOnline() &&
      this.syncState() !== 'syncing',
  );

  /** Hover text for the sync pill: the error, else when it last synced. */
  public syncTooltip = computed(() => {
    if (this.syncState() === 'sync-error') {
      return this.lastSyncError() || 'Local changes could not be synchronized';
    }
    if (!this.isOnline()) return 'Offline — changes are saved on this device';
    const last = this.lastSyncedAt();
    return last
      ? `Last synced ${this.formatLastSynced(last)} — click to sync now`
      : 'Click to sync now';
  });

  public initials = computed(() => {
    const p = this.profile();
    if (!p) return '';
    const words = (p.name?.trim() || p.email)
      .split(/[\s@._-]+/)
      .filter(Boolean);
    const [first = '', second = ''] = words;
    return (
      second ? `${first.charAt(0)}${second.charAt(0)}` : first.slice(0, 2)
    ).toUpperCase();
  });

  public isDevMode = !environment.production;
  public mobileMenuOpen = signal(false);
  public accountMenuOpen = signal(false);
  @ViewChild('accountMenu') private accountMenuRef?: ElementRef<HTMLElement>;
  @ViewChild('accountButton')
  private accountButtonRef?: ElementRef<HTMLButtonElement>;
  public readonly APP_ROUTES = AppRoutes;

  /** The active route asked for the full-height app frame (`data: { appFrame: true }`):
   *  `main` drops its page padding and scroll so the routed screen owns the viewport. */
  public appFrame = signal(false);

  constructor() {
    this.router.events.subscribe((event) => {
      if (event instanceof NavigationEnd) {
        this.closeMobileMenu();
        this.accountMenuOpen.set(false);
        this.appFrame.set(this.deepestRouteFlag('appFrame'));
      }
    });

    // A registered signature is never removed, so only an unknown/missing flag needs
    // confirming (profiles cached before the feature carry no flag).
    if (this.session.profile()?.hasSignature !== true) {
      void this.signatures.refreshStatus();
    }
  }

  public openSignatureDialog(): void {
    this.signatureDialogOpen.set(true);
  }

  public closeSignatureDialog(): void {
    this.signatureDialogOpen.set(false);
  }

  private deepestRouteFlag(key: string): boolean {
    let route = this.router.routerState.snapshot.root;
    while (route.firstChild) route = route.firstChild;
    return route.data[key] === true;
  }

  public toggleMobileMenu(): void {
    this.mobileMenuOpen.update((v) => !v);
  }

  public closeMobileMenu(): void {
    const active = document.activeElement;
    if (active instanceof HTMLElement) {
      active.blur();
    }

    this.mobileMenuOpen.set(false);
  }

  // ---- Account menu (desktop header) ----

  public toggleAccountMenu(): void {
    if (this.accountMenuOpen()) this.closeAccountMenu();
    else this.openAccountMenu();
  }

  /** Opens the menu and moves focus to its first item, like a native menu. */
  public openAccountMenu(): void {
    this.accountMenuOpen.set(true);
    setTimeout(() => this.menuItems()[0]?.focus());
  }

  public closeAccountMenu(restoreFocus = false): void {
    if (!this.accountMenuOpen()) return;
    this.accountMenuOpen.set(false);
    if (restoreFocus) this.accountButtonRef?.nativeElement.focus();
  }

  private menuItems(): HTMLElement[] {
    const root = this.accountMenuRef?.nativeElement;
    return root
      ? Array.from(root.querySelectorAll<HTMLElement>('[role="menuitem"]'))
      : [];
  }

  /** ↑/↓/Home/End move between items; Esc closes back onto the button; Tab leaves. */
  public onAccountMenuKeydown(event: KeyboardEvent): void {
    const items = this.menuItems();
    const index = items.indexOf(document.activeElement as HTMLElement);
    let next: HTMLElement | undefined;
    switch (event.key) {
      case 'ArrowDown':
        next = items[(index + 1) % items.length];
        break;
      case 'ArrowUp':
        next = items[(index - 1 + items.length) % items.length];
        break;
      case 'Home':
        next = items[0];
        break;
      case 'End':
        next = items[items.length - 1];
        break;
      case 'Escape':
        event.preventDefault();
        event.stopPropagation();
        this.closeAccountMenu(true);
        return;
      case 'Tab':
        this.closeAccountMenu();
        return;
      default:
        return;
    }
    event.preventDefault();
    next?.focus();
  }

  @HostListener('document:click', ['$event'])
  public onDocumentClick(event: MouseEvent): void {
    if (!this.accountMenuOpen()) return;
    const root = this.accountMenuRef?.nativeElement;
    if (root && event.target instanceof Node && !root.contains(event.target)) {
      this.closeAccountMenu();
    }
  }

  @HostListener('document:keydown.escape')
  public onDocumentEscape(): void {
    this.closeAccountMenu(true);
  }

  public getProfileLabel(): string {
    const p = this.profile();
    if (!p) return 'Menu';
    return p.name?.trim() || p.email;
  }

  public onSignOut() {
    this.session.logout();
    this.router.navigate(['/login']);
  }

  public async clearSyncErrors() {
    await this.outbox.clearConflicts();
    await this.orchestrator.syncNow();
  }

  public async onSyncNow() {
    if (!this.canSyncNow()) return;
    await this.orchestrator.syncNow();
  }

  public async simulateOfflineMutation() {
    if (!this.isDevMode) return;

    await this.outbox.enqueue({
      id: crypto.randomUUID(),
      idempotencyKey: crypto.randomUUID(),
      createdAt: new Date().toISOString(),
      entityType: 'System',
      entityId: 'dev-ping',
      operation: 'ping',
      payload: {},
      status: 'PENDING',
      attemptCount: 0,
      lastError: null,
    });

    // Auto-trigger sync orchestrator if online so we see it resolve
    if (this.connectivity.isOnline()) {
      await this.orchestrator.syncNow();
    }
  }

  public formatLastSynced(isoStr: string | null): string {
    if (!isoStr) return '';
    const date = new Date(isoStr);
    const today = new Date();

    // Check if it's today
    if (
      date.getDate() === today.getDate() &&
      date.getMonth() === today.getMonth() &&
      date.getFullYear() === today.getFullYear()
    ) {
      return `Today, ${date.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' })}`;
    }

    // Otherwise
    return `${date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}, ${date.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' })}`;
  }
}
